fragment:
vec4 a_orig = texture2D(tex0, v_tex_coord, u_lod_bias);

// 글자 칸 나누기 (칸 크기는 게임 화면 픽셀 기준)
vec2 a_px = v_tex_coord * u_model_size;
vec2 a_cs = max(u_ascii_cellsize, vec2(1.0));
vec2 a_idx = floor(a_px / a_cs);
vec2 a_local = (a_px - a_idx * a_cs) / a_cs;

// 칸의 대표 색: 칸 안 네 곳의 평균
vec2 a_c = (a_idx + 0.5) * a_cs / u_model_size;
vec2 a_q = a_cs * 0.25 / u_model_size;
vec4 a_s = (texture2D(tex0, a_c + vec2(-a_q.x, -a_q.y), u_lod_bias)
          + texture2D(tex0, a_c + vec2( a_q.x, -a_q.y), u_lod_bias)
          + texture2D(tex0, a_c + vec2(-a_q.x,  a_q.y), u_lod_bias)
          + texture2D(tex0, a_c + vec2( a_q.x,  a_q.y), u_lod_bias)) * 0.25;
float a_a = a_s.a;
vec3 a_rgb = (a_a > 0.001) ? a_s.rgb / a_a : vec3(0.0);

// 밝기 → 글자 번호
float a_l = dot(a_rgb, vec3(0.2126, 0.7152, 0.0722));
a_l = clamp(((a_l - 0.5) * u_ascii_contrast + 0.5) * u_ascii_brightness, 0.0, 1.0);
if (u_ascii_invert > 0.5) {
    a_l = 1.0 - a_l;
}
float a_n = max(u_ascii_count, 1.0);
float a_ci = clamp(floor(a_l * a_n), 0.0, a_n - 1.0);

// 글자 그림에서 그 글자의 이 자리
vec2 a_auv = vec2((a_ci + a_local.x) / a_n, a_local.y);
float a_g = texture2D(u_ascii_atlas, a_auv).a;

// 글자 색
vec3 a_fg;
if (u_ascii_color_mode < 0.5) {
    a_fg = u_ascii_fg;
} else {
    a_fg = clamp(a_rgb * u_ascii_color_boost, 0.0, 1.0);
    if (u_ascii_color_mode > 1.5) {
        a_fg = ascii_palette(a_fg);
    }
}

// 바탕: 바탕색에 칸의 원래 색을 조금 비침 (글자 사이가 너무 어두워지지 않게)
vec3 a_bg = mix(u_ascii_bg, a_rgb, clamp(u_ascii_bg_tint, 0.0, 1.0));
vec3 a_out = mix(a_bg, a_fg, a_g);
vec4 a_fx = vec4(a_out * a_a, a_a);

gl_FragColor = mix(a_orig, a_fx, clamp(u_ascii_strength, 0.0, 1.0));

glsl.variables:
uniform sampler2D tex0;
uniform sampler2D u_ascii_atlas;
uniform float u_lod_bias;
uniform vec2 u_model_size;
attribute vec2 a_tex_coord;
varying vec2 v_tex_coord;

uniform float u_ascii_strength;
uniform float u_ascii_cell;
uniform float u_ascii_aspect;
uniform float u_ascii_crisp;
uniform float u_ascii_color_mode;
uniform vec3 u_ascii_fg;
uniform vec3 u_ascii_bg;
uniform float u_ascii_color_boost;
uniform float u_ascii_bg_tint;
uniform float u_ascii_brightness;
uniform float u_ascii_contrast;
uniform float u_ascii_invert;

uniform vec2 u_ascii_cellsize;
uniform float u_ascii_count;

fragment:
vec2 vc_uv0 = v_tex_coord.xy;
vec4 vc_orig = texture2D(tex0, vc_uv0, u_lod_bias);
vec2 vc_res = u_vhs_crt_resolution;

vec2 vc_uv = vhs_crt_warp(vc_uv0, u_vhs_crt_warp_amount);
vec2 vc_tuv = vc_uv;
vec2 vc_roll_uv = vec2(0.0);
float vc_time = (u_vhs_crt_roll > 0.5) ? u_time : 0.0;

if (u_vhs_crt_pixelate > 0.5) {
    vc_tuv = ceil(vc_uv * vc_res) / vc_res;
}

float vc_roll_line = 0.0;
if (u_vhs_crt_roll > 0.5 || u_vhs_crt_noise_opacity > 0.0) {
    vc_roll_line = smoothstep(0.3, 0.9, sin(vc_uv.y * u_vhs_crt_roll_size - (vc_time * u_vhs_crt_roll_speed)));
    vc_roll_line *= vc_roll_line * smoothstep(0.3, 0.9, sin(vc_uv.y * u_vhs_crt_roll_size * u_vhs_crt_roll_variation - (vc_time * u_vhs_crt_roll_speed * u_vhs_crt_roll_variation)));
    vc_roll_uv = vec2(vc_roll_line * u_vhs_crt_distort_intensity * (1.0 - vc_uv0.x), 0.0);
}

vec2 vc_ab = vec2(u_vhs_crt_aberration, 0.0) * 0.1;
float vc_r;
float vc_g;
float vc_b;
float vc_a;

// 텍스처는 투명도가 곱해진 색이라, 투명도로 나눠 원래 색으로 되돌린 뒤 계산합니다.
// (불투명한 화면에서는 그대로, 반투명한 대사창 등에 씌울 때 두 번 어두워지지 않게)
vec2 vc_ruv = (u_vhs_crt_roll > 0.5) ? vc_roll_uv : vec2(0.0);
vec4 vc_sr = texture2D(tex0, vc_tuv + vc_ruv * 0.8 + vc_ab, u_lod_bias);
vec4 vc_sg = texture2D(tex0, vc_tuv + vc_ruv * 1.2 - vc_ab, u_lod_bias);
vec4 vc_s = texture2D(tex0, vc_tuv + vc_ruv, u_lod_bias);
vc_r = vc_sr.r / max(vc_sr.a, 0.0001);
vc_g = vc_sg.g / max(vc_sg.a, 0.0001);
vc_b = vc_s.b / max(vc_s.a, 0.0001);
vc_a = vc_s.a;

if (u_vhs_crt_grille_opacity > 0.0) {
    float vc_gr = smoothstep(0.85, 0.95, abs(sin(vc_uv.x * (vc_res.x * 3.14159265))));
    vc_r = mix(vc_r, vc_r * vc_gr, u_vhs_crt_grille_opacity);
    float vc_gg = smoothstep(0.85, 0.95, abs(sin(1.05 + vc_uv.x * (vc_res.x * 3.14159265))));
    vc_g = mix(vc_g, vc_g * vc_gg, u_vhs_crt_grille_opacity);
    float vc_gb = smoothstep(0.85, 0.95, abs(sin(2.1 + vc_uv.x * (vc_res.x * 3.14159265))));
    vc_b = mix(vc_b, vc_b * vc_gb, u_vhs_crt_grille_opacity);
}

vec3 vc_col = clamp(vec3(vc_r, vc_g, vc_b) * u_vhs_crt_brightness, 0.0, 1.0);

float vc_scan = 0.5;
if (u_vhs_crt_scanlines_opacity > 0.0) {
    vc_scan = smoothstep(u_vhs_crt_scanlines_width, u_vhs_crt_scanlines_width + 0.5, abs(sin(vc_uv.y * (vc_res.y * 3.14159265))));
    vc_col = mix(vc_col, vc_col * vec3(vc_scan), u_vhs_crt_scanlines_opacity);
}

if (u_vhs_crt_noise_opacity > 0.0) {
    float vc_n = smoothstep(0.4, 0.5, vhs_crt_noise(vc_uv * vec2(2.0, 200.0) + vec2(10.0, u_time * u_vhs_crt_noise_speed)));
    vc_roll_line *= vc_n * vc_scan * clamp(vhs_crt_random((ceil(vc_uv * vc_res) / vc_res) + vec2(u_time * 0.8, 0.0)).x + 0.8, 0.0, 1.0);
    vc_col = clamp(mix(vc_col, vc_col + vc_roll_line, u_vhs_crt_noise_opacity), vec3(0.0), vec3(1.0));
}

if (u_vhs_crt_static_noise_intensity > 0.0) {
    vc_col += clamp(vhs_crt_random((ceil(vc_uv * vc_res) / vc_res) + fract(u_time)).x, 0.0, 1.0) * u_vhs_crt_static_noise_intensity;
}

float vc_border = vhs_crt_border(vc_uv, u_vhs_crt_warp_amount);
vc_col *= vc_border;
vc_col *= vhs_crt_vignette(vc_uv, u_vhs_crt_vignette_intensity, u_vhs_crt_vignette_opacity);

if (u_vhs_crt_discolor > 0.5) {
    vec3 vc_grey = vec3(vc_col.r + vc_col.g + vc_col.b) / 3.0;
    vc_col = mix(vc_col, vc_grey, u_vhs_crt_saturation);
    float vc_mid = pow(0.5, 2.2);
    vc_col = (vc_col - vec3(vc_mid)) * u_vhs_crt_contrast + vc_mid;
}

// 화면 전체에 쓸 때는 불투명(1.0) 그대로, 투명한 부분이 있는 이미지에 쓸 때는
// 그 투명도를 유지합니다.
float vc_alpha = vc_a * ((u_vhs_crt_clip_warp > 0.5) ? vc_border : 1.0);
vec4 vc_fx = vec4(clamp(vc_col, 0.0, 1.0) * vc_alpha, vc_alpha);

gl_FragColor = mix(vc_orig, vc_fx, clamp(u_vhs_crt_strength, 0.0, 1.0));

glsl.fragment_functions:
vec2 vhs_crt_random(vec2 uv) {
    uv = vec2(dot(uv, vec2(127.1, 311.7)),
              dot(uv, vec2(269.5, 183.3)));
    return -1.0 + 2.0 * fract(sin(uv) * 43758.5453123);
}

float vhs_crt_noise(vec2 uv) {
    vec2 uv_index = floor(uv);
    vec2 uv_fract = fract(uv);
    vec2 blur = smoothstep(0.0, 1.0, uv_fract);

    return mix(mix(dot(vhs_crt_random(uv_index + vec2(0.0, 0.0)), uv_fract - vec2(0.0, 0.0)),
                   dot(vhs_crt_random(uv_index + vec2(1.0, 0.0)), uv_fract - vec2(1.0, 0.0)), blur.x),
               mix(dot(vhs_crt_random(uv_index + vec2(0.0, 1.0)), uv_fract - vec2(0.0, 1.0)),
                   dot(vhs_crt_random(uv_index + vec2(1.0, 1.0)), uv_fract - vec2(1.0, 1.0)), blur.x),
               blur.y) * 0.5 + 0.5;
}

vec2 vhs_crt_warp(vec2 uv, float amount) {
    vec2 delta = uv - 0.5;
    float delta2 = dot(delta, delta);
    return uv + delta * (delta2 * delta2 * amount);
}

float vhs_crt_border(vec2 uv, float amount) {
    float radius = min(amount, 0.08);
    radius = max(min(abs(radius * 2.0), 1.0), 1e-5);
    vec2 abs_uv = abs(uv * 2.0 - 1.0) - vec2(1.0, 1.0) + radius;
    float dist = length(max(vec2(0.0), abs_uv)) / radius;
    float square = smoothstep(0.96, 1.0, dist);
    return clamp(1.0 - square, 0.0, 1.0);
}

float vhs_crt_vignette(vec2 uv, float intensity, float opacity) {
    uv = clamp(uv, 0.0, 1.0);
    uv *= 1.0 - uv;
    float v = max(uv.x * uv.y * 15.0, 1e-6);
    return pow(v, intensity * opacity);
}

glsl.variables:
uniform sampler2D tex0;
uniform float u_lod_bias;
uniform float u_time;
attribute vec2 a_tex_coord;
varying vec2 v_tex_coord;

uniform float u_vhs_crt_strength;
uniform float u_vhs_crt_scanlines_opacity;
uniform float u_vhs_crt_scanlines_width;
uniform float u_vhs_crt_grille_opacity;
uniform vec2 u_vhs_crt_resolution;
uniform float u_vhs_crt_pixelate;
uniform float u_vhs_crt_roll;
uniform float u_vhs_crt_roll_speed;
uniform float u_vhs_crt_roll_size;
uniform float u_vhs_crt_roll_variation;
uniform float u_vhs_crt_distort_intensity;
uniform float u_vhs_crt_noise_opacity;
uniform float u_vhs_crt_noise_speed;
uniform float u_vhs_crt_static_noise_intensity;
uniform float u_vhs_crt_aberration;
uniform float u_vhs_crt_brightness;
uniform float u_vhs_crt_discolor;
uniform float u_vhs_crt_saturation;
uniform float u_vhs_crt_contrast;
uniform float u_vhs_crt_warp_amount;
uniform float u_vhs_crt_clip_warp;
uniform float u_vhs_crt_vignette_intensity;
uniform float u_vhs_crt_vignette_opacity;

fragment:
vec2 rt_uv0 = v_tex_coord;
vec4 rt_orig = texture2D(tex0, rt_uv0, u_lod_bias);
vec2 rt_px = max(u_model_size, vec2(1.0));
float rt_t = u_time;

// ── 1. 화면 좌표: 테두리만큼 줄이고, 곡면으로 휨 ──
bool rt_crt = u_rt_crt > 0.5;
float rt_fs = (rt_crt && u_rt_frame > 0.5) ? clamp(u_rt_frame_size, 0.0, 0.3) : 0.0;
vec2 rt_uv = (rt_uv0 - 0.5) / (1.0 - 2.0 * rt_fs) + 0.5;
vec2 rt_d = rt_uv - 0.5;
if (rt_crt) {
    rt_uv = rt_uv + rt_d * dot(rt_d, rt_d) * u_rt_curvature;
}
float rt_corner = rt_crt ? clamp(u_rt_corner, 0.0, 0.25) : 0.0;
float rt_sd = rt_screen_dist(rt_uv, rt_corner);
float rt_soft = 1.5 / min(rt_px.x, rt_px.y);
float rt_inside = rt_crt ? (1.0 - smoothstep(-rt_soft, rt_soft, rt_sd)) : 1.0;

// ── 2. 흔들림: 떨림, VHS 흐르는 띠·수평 흔들림 ──
vec2 rt_suv = rt_uv;
if (u_rt_jitter > 0.0) {
    float rt_jf = floor(rt_t * 24.0);
    rt_suv += (vec2(rt_hash(vec2(rt_jf, 1.3)), rt_hash(vec2(rt_jf, 7.1))) - 0.5) * u_rt_jitter * 3.0 / rt_px;
}
float rt_band = 0.0;
if (u_rt_vhs > 0.5) {
    float rt_by = fract(rt_t * 0.08 * u_rt_vhs_roll_speed) * 1.4 - 0.2;
    float rt_dy = abs(rt_suv.y - rt_by);
    rt_band = (1.0 - smoothstep(0.0, 0.07, rt_dy)) * clamp(u_rt_vhs_roll, 0.0, 1.0);
    float rt_w = sin(rt_suv.y * 37.0 + rt_t * 2.3) * 0.6 + sin(rt_suv.y * 151.0 - rt_t * 9.1) * 0.4;
    rt_suv.x += rt_w * u_rt_vhs_wobble * 1.5 / rt_px.x;
    rt_suv.x += rt_band * 10.0 / rt_px.x * sin(rt_suv.y * 400.0 + rt_t * 40.0);
}

// ── 3. 원래 그림 읽기 (RGB 어긋남) ──
vec4 rt_c = texture2D(tex0, rt_suv, u_lod_bias);
vec3 rt_col = rt_unpre(rt_c);
if (u_rt_rgb_shift > 0.0) {
    vec2 rt_sh = vec2(u_rt_rgb_shift / rt_px.x, 0.0);
    rt_col.r = rt_unpre(texture2D(tex0, rt_suv + rt_sh, u_lod_bias)).r;
    rt_col.b = rt_unpre(texture2D(tex0, rt_suv - rt_sh, u_lod_bias)).b;
}
float rt_a = rt_c.a;

// ── 4. 밝기 → 형광체 색 ──
float rt_l = rt_luma(rt_col);
rt_l = clamp((rt_l - 0.5) * u_rt_contrast + 0.5, 0.0, 1.0) * u_rt_brightness;
vec3 rt_light = mix(u_rt_phosphor * rt_l, rt_col * u_rt_brightness, clamp(u_rt_color_keep, 0.0, 1.0));

// ── 5. 화면 결 (곡면을 따라 휨) ──
vec2 rt_p = rt_uv * rt_px;
float rt_pitch = max(u_rt_raster_size, 1.0);
float rt_rs = clamp(u_rt_raster_strength, 0.0, 1.0);
if (u_rt_raster > 0.5) {
    float rt_sl = 0.5 + 0.5 * cos(6.2831853 * rt_p.y / rt_pitch);
    vec3 rt_mask;
    float rt_mean;
    if (u_rt_raster < 1.5) {
        rt_mask = vec3(rt_sl);
        rt_mean = 0.5;
    } else if (u_rt_raster < 2.5) {
        float rt_sc = 0.5 + 0.5 * cos(6.2831853 * rt_p.x / rt_pitch);
        rt_mask = vec3(rt_sl * rt_sc);
        rt_mean = 0.25;
    } else {
        float rt_k = mod(floor(rt_p.x / max(rt_pitch / 3.0, 0.34)), 3.0);
        rt_mask = vec3(rt_k < 0.5 ? 1.0 : 0.3, (rt_k > 0.5 && rt_k < 1.5) ? 1.0 : 0.3, rt_k > 1.5 ? 1.0 : 0.3);
        rt_mask *= mix(1.0, rt_sl, 0.5);
        rt_mean = 0.4;
    }
    // 결 때문에 어두워진 만큼 밝혀서 전체 밝기는 그대로
    rt_light *= mix(vec3(1.0), rt_mask, rt_rs) / mix(1.0, rt_mean, rt_rs);
}

// ── 6. 빛 번짐 (주변 12곳의 밝기를 모아 더함) ──
vec3 rt_glow = vec3(0.0);
float rt_glow_a = 0.0;
if (u_rt_bloom > 0.0) {
    vec2 rt_br = max(u_rt_bloom_size, 0.5) / rt_px;
    vec4 rt_bs = vec4(0.0);
    for (int i = 0; i < 12; i++) {
        float rt_ang = float(i) * 0.5235988 + ((i < 6) ? 0.0 : 0.2617994);
        float rt_rad = (i < 6) ? 1.0 : 2.2;
        rt_bs += texture2D(tex0, rt_suv + vec2(cos(rt_ang), sin(rt_ang)) * rt_br * rt_rad, u_lod_bias);
    }
    rt_bs /= 12.0;
    float rt_bl = rt_luma(rt_bs.rgb);
    vec3 rt_bcol = mix(u_rt_phosphor * rt_bl, rt_bs.rgb, clamp(u_rt_color_keep, 0.0, 1.0));
    rt_glow = rt_bcol * u_rt_bloom * 0.6;
    rt_glow_a = clamp(rt_bs.a * rt_bl * u_rt_bloom, 0.0, 1.0);
}

// ── 7. 지나가는 밝은 줄, 정적 노이즈, VHS 띠 지직거림, 깜빡임 ──
if (u_rt_glow_line > 0.0) {
    float rt_gy = fract(rt_t * u_rt_glow_line_speed) * 1.2 - 0.1;
    float rt_gd = rt_uv.y - rt_gy;
    float rt_g = exp(-abs(rt_gd) * 30.0) + 0.35 * exp(-max(-rt_gd, 0.0) * 6.0) * step(rt_gd, 0.0);
    rt_light += u_rt_phosphor * rt_g * u_rt_glow_line * 0.25;
}
if (u_rt_static_noise > 0.0) {
    float rt_n = rt_hash(floor(rt_p) + vec2(fract(rt_t * 7.13) * 311.0, fract(rt_t * 3.71) * 173.0));
    rt_light += u_rt_phosphor * (rt_n - 0.35) * u_rt_static_noise;
}
if (rt_band > 0.0) {
    float rt_vn = rt_hash(floor(rt_p * vec2(0.5, 1.0)) + vec2(rt_t * 61.0, 0.0));
    rt_light += u_rt_phosphor * rt_band * u_rt_vhs_noise * rt_vn;
}
if (u_rt_flicker > 0.0) {
    rt_light *= 1.0 + (rt_hash(vec2(floor(rt_t * 30.0), 3.7)) - 0.5) * u_rt_flicker * 2.0;
}

// ── 8. 바탕색 + 빛, 유리에 비친 빛, 가장자리 어둡게 ──
float rt_r = length(rt_d);
vec3 rt_scr = u_rt_background + max(rt_light, vec3(0.0));
rt_scr += u_rt_phosphor * u_rt_ambient * 0.2 * (1.0 - smoothstep(0.0, 0.8, rt_r));
if (rt_crt) {
    rt_scr *= 1.0 - clamp(u_rt_vignette, 0.0, 1.0) * smoothstep(0.25, 0.75, rt_r);
}
rt_scr = clamp(rt_scr, 0.0, 1.0);

// 투명도: 그림이 있는 곳만 (투명한 층에 씌워도 바탕색이 다른 층을 덮지 않게)
vec4 rt_screen = vec4(rt_scr * rt_a, rt_a);
rt_screen.rgb += rt_glow;
rt_screen.a = clamp(rt_screen.a + rt_glow_a * (1.0 - rt_screen.a), 0.0, 1.0);
rt_screen.rgb = min(rt_screen.rgb, vec3(rt_screen.a));

// ── 9. 화면 바깥: 테두리 ──
vec4 rt_out = rt_screen;
if (rt_crt) {
    vec3 rt_bez = vec3(0.0);
    if (u_rt_frame > 0.5) {
        vec2 rt_e = clamp(rt_uv, vec2(0.02), vec2(0.98));
        float rt_el = rt_luma(rt_unpre(texture2D(tex0, rt_e, u_lod_bias)));
        float rt_fall = exp(-max(rt_sd, 0.0) * 40.0);
        rt_bez = u_rt_frame_color * (0.75 + 0.25 * (1.0 - smoothstep(0.3, 0.75, length(rt_uv0 - 0.5))));
        rt_bez += u_rt_phosphor * rt_el * u_rt_frame_reflect * 0.35 * rt_fall;
        rt_bez = clamp(rt_bez, 0.0, 1.0);
    }
    // 테두리는 바탕이 되는 층(화면 전체·장면)에만 칠함. 위에 겹치는 글자 층은 투명하게
    float rt_ba = (u_sfx_base > 0.5) ? rt_orig.a : 0.0;
    vec4 rt_bezel = vec4(rt_bez * rt_ba, rt_ba);
    rt_out = mix(rt_bezel, rt_screen, rt_inside);
}

gl_FragColor = mix(rt_orig, rt_out, clamp(u_rt_strength, 0.0, 1.0));

glsl.fragment_functions:
float rt_hash(vec2 p) {
    p = fract(p * vec2(443.897, 441.423));
    p += dot(p, p.yx + 19.19);
    return fract((p.x + p.y) * p.x);
}

// 투명도가 곱해진 색 → 원래 색
vec3 rt_unpre(vec4 c) {
    return (c.a > 0.0001) ? c.rgb / c.a : vec3(0.0);
}

float rt_luma(vec3 c) {
    return dot(c, vec3(0.2126, 0.7152, 0.0722));
}

// 모서리가 둥근 화면 [0,1]x[0,1]까지의 거리 (안쪽이 음수)
float rt_screen_dist(vec2 uv, float r) {
    vec2 q = abs(uv - 0.5) - (0.5 - r);
    return length(max(q, vec2(0.0))) + min(max(q.x, q.y), 0.0) - r;
}

glsl.variables:
uniform sampler2D tex0;
uniform float u_lod_bias;
uniform float u_time;
uniform vec2 u_model_size;
uniform float u_sfx_base;
attribute vec2 a_tex_coord;
varying vec2 v_tex_coord;

uniform float u_rt_strength;
uniform vec3 u_rt_phosphor;
uniform vec3 u_rt_background;
uniform float u_rt_color_keep;
uniform float u_rt_brightness;
uniform float u_rt_contrast;
uniform float u_rt_ambient;

uniform float u_rt_bloom;
uniform float u_rt_bloom_size;
uniform float u_rt_flicker;
uniform float u_rt_glow_line;
uniform float u_rt_glow_line_speed;

uniform float u_rt_raster;
uniform float u_rt_raster_size;
uniform float u_rt_raster_strength;
uniform float u_rt_static_noise;
uniform float u_rt_jitter;
uniform float u_rt_rgb_shift;

uniform float u_rt_crt;
uniform float u_rt_curvature;
uniform float u_rt_vignette;
uniform float u_rt_frame;
uniform float u_rt_frame_size;
uniform vec3 u_rt_frame_color;
uniform float u_rt_frame_reflect;
uniform float u_rt_corner;

uniform float u_rt_vhs;
uniform float u_rt_vhs_roll;
uniform float u_rt_vhs_roll_speed;
uniform float u_rt_vhs_wobble;
uniform float u_rt_vhs_noise;

fragment:
vec2 gb_uv = v_tex_coord;
vec4 gb_orig = texture2D(tex0, gb_uv, u_lod_bias);
vec2 gb_size = max(u_model_size, vec2(1.0));
float gb_n = (u_gb_colors < 0.5) ? 4.0 : 2.0;
vec3 gb_tn = vec3(u_gb_gamma, u_gb_contrast, u_gb_brightness);
vec3 gb_dm = vec3(u_gb_mode, u_gb_dither, u_gb_dither_strength);
vec4 gb_out;

if (u_sfx_text > 0.5 && u_gb_text_pixel < 0.5) {

    // ── 글자 층: 색만 입힘 (점으로 쪼개지 않아서 글자가 그대로 읽힘) ──
    float gb_k = floor(gb_tone(gb_unpre(gb_orig), gb_tn) * (gb_n - 1.0) + 0.5);
    gb_out = vec4(gb_pal(gb_k, gb_n, u_gb_color1, u_gb_color2, u_gb_color3, u_gb_color4) * gb_orig.a, gb_orig.a);

} else {

    // ── 1. 점 나누기: 화면 가운데를 기준으로 점 크기만큼 칸을 나눔 ──
    float gb_ps = max(floor(u_gb_pixel_size + 0.5), 1.0);
    vec2 gb_p = gb_uv * gb_size;
    vec2 gb_org = floor(gb_size * 0.5);
    vec2 gb_cell = floor((gb_p - gb_org) / gb_ps);
    vec2 gb_f = (gb_p - gb_org) / gb_ps - gb_cell;

    // ── 2. 점의 평균 색 → 단계 (디더링 / 픽셀화) → 팔레트 색 ──
    vec4 gb_avg = gb_dot(gb_cell, gb_org, gb_ps, gb_size);
    float gb_a = gb_avg.a;
    float gb_k = gb_level(gb_tone(gb_unpre(gb_avg), gb_tn), gb_cell, gb_n, gb_dm);
    vec3 gb_col = gb_pal(gb_k, gb_n, u_gb_color1, u_gb_color2, u_gb_color3, u_gb_color4);

    // ── 3. 점 사이 틈: 가장 밝은 색보다 조금 더 밝은 바탕이 비침 ──
    // 경계 부드럽기: 실제 화면의 한 픽셀 정도
    float gb_aa = clamp(gb_size.x / max(u_drawable_size.x, 1.0), 0.3, 2.0) * 0.5 / gb_ps;
    float gb_shape = 1.0;
    if (u_gb_grid > 0.0 && u_gb_grid_width > 0.0 && gb_ps >= 2.0) {
        gb_shape = mix(1.0, gb_dotmask(gb_f, u_gb_grid_width, gb_aa), clamp(u_gb_grid, 0.0, 1.0));
    }
    vec3 gb_gap = min(u_gb_color4 * 1.06 + 0.02, vec3(1.0));
    vec3 gb_scr = mix(gb_gap, gb_col, gb_shape);

    // ── 4. 점 그림자: 왼쪽 위에 있는 더 어두운 점의 그림자가 오른쪽 아래로 떨어짐 ──
    if (u_gb_shadow > 0.0 && u_gb_shadow_offset > 0.0) {
        vec2 gb_q = gb_p - vec2(u_gb_shadow_offset * gb_ps);
        vec2 gb_qc = floor((gb_q - gb_org) / gb_ps);
        vec2 gb_qf = (gb_q - gb_org) / gb_ps - gb_qc;
        vec4 gb_qa = gb_dot(gb_qc, gb_org, gb_ps, gb_size);
        float gb_qk = gb_level(gb_tone(gb_unpre(gb_qa), gb_tn), gb_qc, gb_n, gb_dm);
        // 지금 자리의 밝기 단계 (틈이면 가장 밝음)
        float gb_here = mix(gb_n - 1.0, gb_k, gb_shape);
        float gb_dk = clamp((gb_here - gb_qk) / max(gb_n - 1.0, 1.0), 0.0, 1.0) * gb_qa.a;
        // 그림자 모양은 점 모양을 부드럽게 한 것
        float gb_qs = (gb_ps >= 2.0) ? gb_dotmask(gb_qf, u_gb_grid_width * clamp(u_gb_grid, 0.0, 1.0), 0.18) : 1.0;
        gb_scr = mix(gb_scr, u_gb_color1, clamp(u_gb_shadow, 0.0, 1.0) * gb_dk * gb_qs * 0.55);
    }

    // ── 5. LCD 얼룩: 비스듬한 결과 넓은 얼룩 (움직이지 않음) ──
    if (u_gb_texture > 0.0) {
        vec2 gb_r = vec2(gb_p.x * 0.8660 + gb_p.y * 0.5, -gb_p.x * 0.5 + gb_p.y * 0.8660);
        float gb_t = gb_noise(gb_r * vec2(0.012, 0.09)) * 0.55 + gb_noise(gb_p * 0.006 + 17.0) * 0.45;
        gb_scr *= 1.0 + (gb_t - 0.5) * u_gb_texture * 0.35;
    }

    gb_scr = clamp(gb_scr, 0.0, 1.0);
    gb_out = vec4(gb_scr * gb_a, gb_a);
}

gl_FragColor = mix(gb_orig, gb_out, clamp(u_gb_strength, 0.0, 1.0));

glsl.fragment_functions:
float gb_hash(vec2 p) {
    p = fract(p * vec2(443.897, 441.423));
    p += dot(p, p.yx + 19.19);
    return fract((p.x + p.y) * p.x);
}

// 부드러운 얼룩 (값 노이즈)
float gb_noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = gb_hash(i);
    float b = gb_hash(i + vec2(1.0, 0.0));
    float c = gb_hash(i + vec2(0.0, 1.0));
    float d = gb_hash(i + vec2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// 순서 디더링 무늬 (Bayer). 점 번호 → 0~1 사이의 문턱값
float gb_bayer2(vec2 a) {
    a = mod(floor(a), 2.0);
    return fract(dot(a, vec2(0.5, a.y * 0.75)));
}

float gb_bayer4(vec2 a) {
    return gb_bayer2(a * 0.5) * 0.25 + gb_bayer2(a);
}

float gb_bayer8(vec2 a) {
    return gb_bayer4(a * 0.5) * 0.25 + gb_bayer2(a);
}

// 투명도가 곱해진 색 → 원래 색
vec3 gb_unpre(vec4 c) {
    return (c.a > 0.0001) ? c.rgb / c.a : vec3(0.0);
}

// 색 → 밝기 (감마, 대비, 밝기 조절 후 0~1). t = (감마, 대비, 밝기)
float gb_tone(vec3 c, vec3 t) {
    float l = dot(c, vec3(0.2126, 0.7152, 0.0722));
    l = pow(clamp(l, 0.0, 1.0), max(t.x, 0.05));
    l = (l - 0.5) * t.y + 0.5;
    return clamp(l * t.z, 0.0, 1.0);
}

// 단계 번호(0 = 가장 어두움) → 팔레트 색. 2색이면 1번과 4번만 씀
vec3 gb_pal(float k, float n, vec3 c1, vec3 c2, vec3 c3, vec3 c4) {
    float i = floor(k * 3.0 / max(n - 1.0, 1.0) + 0.5);
    if (i < 0.5) return c1;
    if (i < 1.5) return c2;
    if (i < 2.5) return c3;
    return c4;
}

// 밝기 → 단계 번호. 디더링이면 점마다 문턱값이 다름
// d = (표현 방식: 0 디더링 / 1 픽셀화, 무늬: 0 4×4 / 1 8×8, 디더링 세기)
float gb_level(float l, vec2 cell, float n, vec3 d) {
    float v = l * (n - 1.0);
    float b = floor(v);
    float thr = 0.5;
    if (d.x < 0.5) {
        float m = (d.y < 0.5) ? (gb_bayer4(cell) + 0.5 / 16.0) : (gb_bayer8(cell) + 0.5 / 64.0);
        thr = mix(0.5, m, clamp(d.z, 0.0, 1.0));
    }
    return min(b + step(thr, v - b), n - 1.0);
}

// 점 하나의 평균 색 (투명도가 곱해진 채로). 점 안의 네 곳을 읽음
vec4 gb_dot(vec2 cell, vec2 org, float ps, vec2 size) {
    vec2 c = org + (cell + 0.5) * ps;
    vec2 lo = 0.5 / size;
    vec2 hi = 1.0 - lo;
    if (ps < 2.0) {
        return texture2D(tex0, clamp(c / size, lo, hi), u_lod_bias);
    }
    float o = ps * 0.25;
    vec4 s = texture2D(tex0, clamp((c + vec2(-o, -o)) / size, lo, hi), u_lod_bias);
    s += texture2D(tex0, clamp((c + vec2(o, -o)) / size, lo, hi), u_lod_bias);
    s += texture2D(tex0, clamp((c + vec2(-o, o)) / size, lo, hi), u_lod_bias);
    s += texture2D(tex0, clamp((c + vec2(o, o)) / size, lo, hi), u_lod_bias);
    return s * 0.25;
}

// 점 모양: 점 안이면 1, 점 사이 틈(점의 오른쪽·아래 가장자리)이면 0
// f = 점 안의 위치 0~1, w = 틈 두께(점 크기의 비율), s = 경계 부드럽기
float gb_dotmask(vec2 f, float w, float s) {
    float x = 1.0 - smoothstep(1.0 - w - s, 1.0 - w + s, f.x);
    float y = 1.0 - smoothstep(1.0 - w - s, 1.0 - w + s, f.y);
    return x * y;
}

glsl.variables:
uniform sampler2D tex0;
uniform float u_lod_bias;
uniform vec2 u_model_size;
uniform vec2 u_drawable_size;
uniform float u_sfx_text;
attribute vec2 a_tex_coord;
varying vec2 v_tex_coord;

uniform float u_gb_strength;
uniform float u_gb_mode;
uniform float u_gb_pixel_size;
uniform float u_gb_dither;
uniform float u_gb_dither_strength;
uniform float u_gb_text_pixel;

uniform float u_gb_colors;
uniform vec3 u_gb_color1;
uniform vec3 u_gb_color2;
uniform vec3 u_gb_color3;
uniform vec3 u_gb_color4;
uniform float u_gb_brightness;
uniform float u_gb_contrast;
uniform float u_gb_gamma;

uniform float u_gb_grid;
uniform float u_gb_grid_width;
uniform float u_gb_shadow;
uniform float u_gb_shadow_offset;
uniform float u_gb_texture;

fragment:
vec2 gc_size = max(u_model_size, vec2(1.0));
vec2 gc_p = v_tex_coord * gc_size;
vec4 gc_orig = texture2D(tex0, v_tex_coord, u_lod_bias);

// ── 1. 지금 망가지는 중인지: 시간을 "한 번 길이"로 나눈 칸마다 주사위 ──
float gc_len = max(u_glitch_length, 0.02);
float gc_slot = floor(u_time / gc_len);
float gc_p_on = clamp(u_glitch_rate * gc_len, 0.0, 1.0);
float gc_on = (u_glitch_always > 0.5) ? 1.0 : step(gc_hash(vec2(gc_slot, 3.7)), gc_p_on);
// 망가지는 동안에도 1초에 20번 모양이 바뀜
float gc_sub = floor(u_time * 20.0);
float gc_e = gc_on * u_glitch_amount * (0.4 + 0.6 * gc_hash(vec2(gc_slot, 9.1)));

vec4 gc_out = gc_orig;

if (gc_e > 0.001) {
    vec2 gc_q = gc_p;

    // ── 2. 가로 띠 찢김 ──
    float gc_bh = max(u_glitch_band, 2.0) * (0.5 + gc_hash(vec2(gc_sub, 1.3)));
    float gc_bi = floor(gc_p.y / gc_bh);
    float gc_bh2 = gc_hash(vec2(gc_bi, gc_sub));
    if (gc_bh2 > 0.55) {
        gc_q.x += (gc_hash(vec2(gc_bi + 7.0, gc_sub)) - 0.5) * 2.0 * u_glitch_tear * gc_e;
    }

    // ── 3. 블록 밀림: 엉뚱한 자리의 네모를 가져옴 ──
    vec2 gc_bs = max(u_glitch_block_size, 4.0) * vec2(1.0 + gc_hash(vec2(gc_sub, 5.5)), 0.5 + 0.5 * gc_hash(vec2(gc_sub, 6.6)));
    vec2 gc_cell = floor(gc_q / gc_bs);
    float gc_ch = gc_hash(gc_cell + vec2(gc_sub * 1.7, gc_sub * 0.3));
    float gc_blk = 0.0;
    if (gc_ch < u_glitch_blocks * 0.35 * min(gc_e, 1.0)) {
        vec2 gc_jump = floor((vec2(gc_hash(gc_cell + 11.0 + gc_sub), gc_hash(gc_cell + 23.0 + gc_sub)) - 0.5) * 6.0);
        gc_q += gc_jump * gc_bs;
        gc_blk = 1.0;
    }

    // ── 4. 색 갈라짐 ──
    float gc_s = u_glitch_rgb_split * gc_e * (0.5 + gc_hash(vec2(gc_sub, 2.2)));
    vec4 gc_r = gc_tex(gc_q + vec2(gc_s, 0.0), gc_size);
    vec4 gc_g = gc_tex(gc_q, gc_size);
    vec4 gc_b = gc_tex(gc_q - vec2(gc_s, 0.0), gc_size);
    float gc_a = max(gc_g.a, max(gc_r.a, gc_b.a));
    vec3 gc_col = vec3(gc_r.r, gc_g.g, gc_b.b);

    // 가져온 블록은 가끔 색이 뒤집히거나 한 색만 남음
    if (gc_blk > 0.5) {
        float gc_k = gc_hash(gc_cell + 41.0 + gc_sub);
        if (gc_k < 0.25) gc_col = vec3(gc_a) - gc_col;
        else if (gc_k < 0.5) gc_col = vec3(gc_col.r, 0.0, gc_col.b);
    }

    // ── 5. 지지직 줄: 하얀 가로줄이 잠깐 ──
    if (u_glitch_noise > 0.0) {
        float gc_line = floor(gc_p.y / 2.0);
        float gc_n = gc_hash(vec2(gc_line, gc_sub * 3.1));
        float gc_w = step(1.0 - 0.04 * u_glitch_noise * min(gc_e, 1.0), gc_n);
        gc_col = mix(gc_col, vec3(gc_a), gc_w * gc_hash(vec2(gc_p.x * 0.05, gc_line + gc_sub)));
    }

    gc_out = vec4(min(gc_col, vec3(gc_a)), gc_a);
}

gl_FragColor = mix(gc_orig, gc_out, clamp(u_glitch_strength, 0.0, 1.0));

glsl.fragment_functions:
float gc_hash(vec2 p) {
    p = fract(p * vec2(443.897, 441.423));
    p += dot(p, p.yx + 19.19);
    return fract((p.x + p.y) * p.x);
}

vec4 gc_tex(vec2 px, vec2 size) {
    vec2 lo = 0.5 / size;
    return texture2D(tex0, clamp(px / size, lo, 1.0 - lo), u_lod_bias);
}

glsl.variables:
uniform sampler2D tex0;
uniform float u_lod_bias;
uniform float u_time;
uniform vec2 u_model_size;
attribute vec2 a_tex_coord;
varying vec2 v_tex_coord;

uniform float u_glitch_strength;
uniform float u_glitch_rate;
uniform float u_glitch_length;
uniform float u_glitch_always;
uniform float u_glitch_amount;
uniform float u_glitch_tear;
uniform float u_glitch_band;
uniform float u_glitch_blocks;
uniform float u_glitch_block_size;
uniform float u_glitch_rgb_split;
uniform float u_glitch_noise;

fragment:
vec2 bo_size = max(u_model_size, vec2(1.0));
vec2 bo_p = v_tex_coord * bo_size;
vec4 bo_orig = texture2D(tex0, v_tex_coord, u_lod_bias);

// ── 1. 시간을 뚝뚝 끊음 (1초에 fps번만 바뀜) ──
float bo_frame = floor(u_time * max(u_boil_fps, 0.1));
vec2 bo_fo = vec2(fract(bo_frame * 0.6180339) * 97.0, fract(bo_frame * 0.4142135) * 89.0);

// ── 2. 자리마다 조금씩 다르게 밀기 (떨림 무늬) ──
vec2 bo_np = bo_p / max(u_boil_scale, 1.0) + bo_fo;
vec2 bo_d = vec2(bo_noise(bo_np), bo_noise(bo_np + vec2(31.7, 17.3))) - 0.5;
vec2 bo_q = bo_p + bo_d * 2.0 * u_boil_amount;

// ── 3. 살짝 번짐: 가까운 네 곳을 같이 읽음 ──
vec4 bo_c = bo_tex(bo_q, bo_size);
if (u_boil_soft > 0.0) {
    float bo_r = 0.75;
    vec4 bo_s = bo_tex(bo_q + vec2(bo_r, 0.0), bo_size) + bo_tex(bo_q - vec2(bo_r, 0.0), bo_size)
              + bo_tex(bo_q + vec2(0.0, bo_r), bo_size) + bo_tex(bo_q - vec2(0.0, bo_r), bo_size);
    bo_c = mix(bo_c, bo_s * 0.25, clamp(u_boil_soft, 0.0, 1.0) * 0.8);
}

// ── 4. 알갱이: 바뀔 때마다 새로 (투명도를 곱한 색이라 그대로 더해도 됨) ──
if (u_boil_grain > 0.0) {
    vec2 bo_g = floor(bo_p / max(u_boil_grain_size, 1.0));
    float bo_n = bo_hash(bo_g + bo_fo * 3.0) - 0.5;
    bo_c.rgb = clamp(bo_c.rgb + bo_n * u_boil_grain * bo_c.a, vec3(0.0), vec3(bo_c.a));
}

gl_FragColor = mix(bo_orig, bo_c, clamp(u_boil_strength, 0.0, 1.0));

glsl.fragment_functions:
float bo_hash(vec2 p) {
    p = fract(p * vec2(443.897, 441.423));
    p += dot(p, p.yx + 19.19);
    return fract((p.x + p.y) * p.x);
}

float bo_noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = bo_hash(i);
    float b = bo_hash(i + vec2(1.0, 0.0));
    float c = bo_hash(i + vec2(0.0, 1.0));
    float d = bo_hash(i + vec2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

vec4 bo_tex(vec2 px, vec2 size) {
    vec2 lo = 0.5 / size;
    return texture2D(tex0, clamp(px / size, lo, 1.0 - lo), u_lod_bias);
}

glsl.variables:
uniform sampler2D tex0;
uniform float u_lod_bias;
uniform float u_time;
uniform vec2 u_model_size;
attribute vec2 a_tex_coord;
varying vec2 v_tex_coord;

uniform float u_boil_strength;
uniform float u_boil_amount;
uniform float u_boil_fps;
uniform float u_boil_scale;
uniform float u_boil_grain;
uniform float u_boil_grain_size;
uniform float u_boil_soft;

fragment:
vec2 ht_size = max(u_model_size, vec2(1.0));
vec2 ht_p = v_tex_coord * ht_size;
vec4 ht_orig = texture2D(tex0, v_tex_coord, u_lod_bias);
vec3 ht_col = u_halftone_paper;
vec3 ht_o3 = vec3(u_halftone_cell, u_halftone_mode, u_halftone_shape);
vec2 ht_bc = vec2(u_halftone_brightness, u_halftone_contrast);

if (u_halftone_mode < 0.5) {
    ht_col = mix(u_halftone_paper, u_halftone_ink, ht_plate(ht_p, ht_size, u_halftone_angle, 0.0, ht_o3, ht_bc));
} else {
    // 인쇄처럼 판마다 각도를 다르게 (기본 45도일 때 하늘 15, 분홍 75, 노랑 0, 검정 45)
    float ht_o = u_halftone_angle - 45.0;
    ht_col *= mix(vec3(1.0), vec3(0.0, 0.68, 0.94), ht_plate(ht_p, ht_size, 15.0 + ht_o, 1.0, ht_o3, ht_bc));
    ht_col *= mix(vec3(1.0), vec3(0.93, 0.0, 0.55), ht_plate(ht_p, ht_size, 75.0 + ht_o, 2.0, ht_o3, ht_bc));
    ht_col *= mix(vec3(1.0), vec3(1.0, 0.92, 0.0), ht_plate(ht_p, ht_size, 0.0 + ht_o, 3.0, ht_o3, ht_bc));
    ht_col = mix(ht_col, u_halftone_ink, ht_plate(ht_p, ht_size, 45.0 + ht_o, 0.0, ht_o3, ht_bc));
}

vec4 ht_out = vec4(ht_col * ht_orig.a, ht_orig.a);
gl_FragColor = mix(ht_orig, ht_out, clamp(u_halftone_strength, 0.0, 1.0));

glsl.fragment_functions:
vec3 ht_unpre(vec4 c) {
    return (c.a > 0.0001) ? c.rgb / c.a : vec3(0.0);
}

// bc = (밝기, 대비)
vec3 ht_adjust(vec3 c, vec2 bc) {
    c = (c - 0.5) * bc.y + 0.5;
    return clamp(c * bc.x, 0.0, 1.0);
}

// 한 각도의 망점 판: 점 칸 가운데의 색을 읽고, ch번 잉크가 얼마나 덮는지(0~1)
// ch: 0 검정(한 색이면 밝기), 1 하늘색, 2 분홍, 3 노랑
// o = (점 간격, 색: 0 한 색 / 1 네 색, 모양: 0 점 / 1 줄), bc = (밝기, 대비)
float ht_plate(vec2 p, vec2 size, float deg, float ch, vec3 o, vec2 bc) {
    float cs = max(o.x, 2.0);
    float a = radians(deg);
    float c = cos(a);
    float s = sin(a);
    vec2 ctr = size * 0.5;
    vec2 d = p - ctr;
    vec2 r = vec2(c * d.x + s * d.y, -s * d.x + c * d.y);
    vec2 cell = floor(r / cs);
    vec2 f = r / cs - cell;
    vec2 cc = (cell + 0.5) * cs;
    vec2 sp = vec2(c * cc.x - s * cc.y, s * cc.x + c * cc.y) + ctr;
    vec2 lo = 0.5 / size;
    vec3 col = ht_adjust(ht_unpre(texture2D(tex0, clamp(sp / size, lo, 1.0 - lo), u_lod_bias)), bc);

    float k = 1.0 - max(col.r, max(col.g, col.b));
    float v;
    if (o.y < 0.5) {
        v = 1.0 - dot(col, vec3(0.299, 0.587, 0.114));
    } else if (ch < 0.5) {
        v = k;
    } else {
        float m = 1.0 / max(1.0 - k, 0.0001);
        if (ch < 1.5) v = (1.0 - col.r - k) * m;
        else if (ch < 2.5) v = (1.0 - col.g - k) * m;
        else v = (1.0 - col.b - k) * m;
    }
    v = clamp(v, 0.0, 1.0);

    float aa = 0.8;
    float dist;
    float rad;
    if (o.z < 0.5) {
        dist = length((f - 0.5) * cs);
        rad = sqrt(v) * cs * 0.7071;
    } else {
        dist = abs(f.y - 0.5) * cs;
        rad = v * cs * 0.5;
    }
    return (v <= 0.001) ? 0.0 : 1.0 - smoothstep(rad - aa, rad + aa, dist);
}

glsl.variables:
uniform sampler2D tex0;
uniform float u_lod_bias;
uniform vec2 u_model_size;
attribute vec2 a_tex_coord;
varying vec2 v_tex_coord;

uniform float u_halftone_strength;
uniform float u_halftone_mode;
uniform float u_halftone_shape;
uniform float u_halftone_cell;
uniform float u_halftone_angle;
uniform vec3 u_halftone_ink;
uniform vec3 u_halftone_paper;
uniform float u_halftone_brightness;
uniform float u_halftone_contrast;

fragment:
vec2 hg_size = max(u_model_size, vec2(1.0));
vec2 hg_p = v_tex_coord * hg_size;
vec4 hg_orig = texture2D(tex0, v_tex_coord, u_lod_bias);

// ── 1. 가끔 가로 띠가 옆으로 튐 ──
float hg_fr = floor(u_time * 12.0);
float hg_band = floor(hg_p.y / 20.0);
float hg_jh = hg_hash(vec2(hg_band, hg_fr));
vec2 hg_q = hg_p;
if (hg_jh > 0.93) hg_q.x += (hg_hash(vec2(hg_band + 3.0, hg_fr)) - 0.5) * 2.0 * u_hologram_jitter;

// ── 2. 본체 + 옆으로 번진 복사본 두 겹 ──
vec4 hg_s0 = hg_tex(hg_q, hg_size);
vec4 hg_s1 = hg_tex(hg_q - vec2(u_hologram_smear, 0.0), hg_size);
vec4 hg_s2 = hg_tex(hg_q - vec2(u_hologram_smear2, 0.0), hg_size);
float hg_sa = u_hologram_smear_alpha;
float hg_l = hg_lum(hg_s0) + hg_sa * (0.6 * hg_lum(hg_s1) + 0.35 * hg_lum(hg_s2));
float hg_a = clamp(hg_s0.a + hg_sa * (0.6 * hg_s1.a + 0.35 * hg_s2.a), 0.0, 1.0);

// ── 3. 빛 번짐: 둘레 여덟 곳의 밝기 ──
if (u_hologram_glow > 0.0) {
    float hg_r = u_hologram_glow_size;
    float hg_g = 0.0;
    float hg_ga = 0.0;
    for (int i = 0; i < 8; i++) {
        float an = float(i) * 0.785398;
        vec4 s = hg_tex(hg_q + vec2(cos(an), sin(an)) * hg_r, hg_size);
        hg_g += hg_lum(s);
        hg_ga += s.a;
    }
    hg_l += u_hologram_glow * hg_g / 8.0 * 0.8;
    hg_a = max(hg_a, clamp(u_hologram_glow * hg_ga / 8.0 * 0.6, 0.0, 1.0));
}

// ── 4. 한 색으로: 밝은 곳은 하얗게 ──
float hg_b = hg_l * u_hologram_brightness;
vec3 hg_col = u_hologram_color * (hg_b + 0.08 * hg_a);
hg_col = mix(hg_col, vec3(hg_a), smoothstep(0.75, 1.3, hg_b) * 0.5);

// ── 5. 주사선 (천천히 흐름) + 깜빡임 ──
float hg_ln = max(u_hologram_lines, 1.0);
float hg_ph = fract((hg_p.y + u_time * u_hologram_line_speed) / hg_ln);
float hg_lf = 1.0 - u_hologram_line_dark * smoothstep(0.35, 0.65, abs(hg_ph - 0.5) * 2.0);
float hg_fl = 1.0 + (hg_hash(vec2(floor(u_time * 20.0), 5.0)) - 0.5) * 2.0 * u_hologram_flicker;
hg_col *= hg_lf * hg_fl;

hg_a *= clamp(u_hologram_opacity, 0.0, 1.0);
hg_col *= clamp(u_hologram_opacity, 0.0, 1.0);
vec4 hg_out = vec4(clamp(hg_col, vec3(0.0), vec3(hg_a)), hg_a);
gl_FragColor = mix(hg_orig, hg_out, clamp(u_hologram_strength, 0.0, 1.0));

glsl.fragment_functions:
float hg_hash(vec2 p) {
    p = fract(p * vec2(443.897, 441.423));
    p += dot(p, p.yx + 19.19);
    return fract((p.x + p.y) * p.x);
}

// 투명도를 곱한 그대로 읽음 (바깥은 투명)
vec4 hg_tex(vec2 px, vec2 size) {
    vec2 uv = px / size;
    if (uv.x < 0.0 || uv.y < 0.0 || uv.x > 1.0 || uv.y > 1.0) return vec4(0.0);
    return texture2D(tex0, uv, u_lod_bias);
}

float hg_lum(vec4 c) {
    return dot(c.rgb, vec3(0.299, 0.587, 0.114));
}

glsl.variables:
uniform sampler2D tex0;
uniform float u_lod_bias;
uniform float u_time;
uniform vec2 u_model_size;
attribute vec2 a_tex_coord;
varying vec2 v_tex_coord;

uniform float u_hologram_strength;
uniform vec3 u_hologram_color;
uniform float u_hologram_brightness;
uniform float u_hologram_opacity;
uniform float u_hologram_lines;
uniform float u_hologram_line_dark;
uniform float u_hologram_line_speed;
uniform float u_hologram_smear;
uniform float u_hologram_smear2;
uniform float u_hologram_smear_alpha;
uniform float u_hologram_glow;
uniform float u_hologram_glow_size;
uniform float u_hologram_flicker;
uniform float u_hologram_jitter;

fragment:
vec2 nv_size = max(u_model_size, vec2(1.0));
vec2 nv_p = v_tex_coord * nv_size;
vec4 nv_orig = texture2D(tex0, v_tex_coord, u_lod_bias);

// ── 1. 살짝 번짐 ──
vec4 nv_c = nv_orig;
if (u_nightvision_soft > 0.0) {
    float nv_r = 1.5;
    vec4 nv_s = nv_tex(nv_p + vec2(nv_r, nv_r), nv_size) + nv_tex(nv_p + vec2(-nv_r, nv_r), nv_size)
              + nv_tex(nv_p + vec2(nv_r, -nv_r), nv_size) + nv_tex(nv_p + vec2(-nv_r, -nv_r), nv_size);
    nv_c = mix(nv_c, nv_s * 0.25, clamp(u_nightvision_soft, 0.0, 1.0) * 0.7);
}
float nv_a = nv_c.a;

// ── 2. 밝기만 남겨 끌어올림 ──
float nv_l = (nv_a > 0.0001) ? dot(nv_c.rgb / nv_a, vec3(0.299, 0.587, 0.114)) : 0.0;
nv_l = pow(clamp(nv_l, 0.0, 1.0), max(u_nightvision_gamma, 0.05)) * u_nightvision_gain;

// ── 3. 노이즈 (어두운 곳일수록 많이, 1초에 30번 바뀜) ──
float nv_fr = floor(u_time * 30.0);
vec2 nv_g = floor(nv_p / max(u_nightvision_noise_size, 1.0));
float nv_n = nv_hash(nv_g + vec2(nv_fr * 1.37, nv_fr * 0.71)) - 0.5;
nv_l += nv_n * u_nightvision_noise * (1.2 - clamp(nv_l, 0.0, 1.0));

// ── 4. 가로줄, 깜빡임 ──
nv_l *= 1.0 - u_nightvision_scanlines * step(0.5, fract(nv_p.y / 3.0));
nv_l *= 1.0 + (nv_hash(vec2(nv_fr, 4.0)) - 0.5) * 2.0 * u_nightvision_flicker;

// ── 5. 한 색으로, 아주 밝은 곳은 하얗게 ──
nv_l = max(nv_l, 0.0);
vec3 nv_col = u_nightvision_color * nv_l;
nv_col = mix(nv_col, vec3(1.0), smoothstep(0.9, 1.6, nv_l) * 0.6);

// ── 6. 가장자리 어둡게, 동그란 테두리 ──
vec2 nv_d = (v_tex_coord - 0.5) * vec2(nv_size.x / nv_size.y, 1.0);
float nv_dist = length(nv_d);
nv_col *= 1.0 - u_nightvision_vignette * smoothstep(0.25, 0.95, nv_dist);
if (u_nightvision_scope > 0.5) {
    nv_col *= 1.0 - smoothstep(0.47, 0.49, nv_dist);
}

vec4 nv_out = vec4(clamp(nv_col, 0.0, 1.0) * nv_a, nv_a);
gl_FragColor = mix(nv_orig, nv_out, clamp(u_nightvision_strength, 0.0, 1.0));

glsl.fragment_functions:
float nv_hash(vec2 p) {
    p = fract(p * vec2(443.897, 441.423));
    p += dot(p, p.yx + 19.19);
    return fract((p.x + p.y) * p.x);
}

vec4 nv_tex(vec2 px, vec2 size) {
    vec2 lo = 0.5 / size;
    return texture2D(tex0, clamp(px / size, lo, 1.0 - lo), u_lod_bias);
}

glsl.variables:
uniform sampler2D tex0;
uniform float u_lod_bias;
uniform float u_time;
uniform vec2 u_model_size;
attribute vec2 a_tex_coord;
varying vec2 v_tex_coord;

uniform float u_nightvision_strength;
uniform vec3 u_nightvision_color;
uniform float u_nightvision_gain;
uniform float u_nightvision_gamma;
uniform float u_nightvision_noise;
uniform float u_nightvision_noise_size;
uniform float u_nightvision_soft;
uniform float u_nightvision_scanlines;
uniform float u_nightvision_vignette;
uniform float u_nightvision_scope;
uniform float u_nightvision_flicker;
uniform float u_nightvision_hud;
uniform float u_nightvision_timer;

fragment:
vec2 sh_size = max(u_model_size, vec2(1.0));
vec2 sh_p = v_tex_coord * sh_size;
vec4 sh_orig = texture2D(tex0, v_tex_coord, u_lod_bias);

float sh_an = radians(u_shards_direction);
// 0도 = 오른쪽으로, 90도 = 아래로 (화면 좌표)
vec2 sh_dir = vec2(cos(sh_an), sin(sh_an));
float sh_ncol = u_shards_colors + 1.0;
float sh_smin = min(u_shards_size_min, u_shards_size_max);
float sh_smax = max(u_shards_size_min, u_shards_size_max);

vec4 sh_acc = vec4(0.0);
float sh_n = max(u_shards_count, 0.0);
if (sh_n >= 1.0) {
    float sh_area = sh_size.x * sh_size.y;
    for (int i = 0; i < 3; i++) {
        float L = float(i);                     // 0 먼 겹, 2 가까운 겹
        float scale = 0.45 + 0.35 * L;          // 0.45, 0.8, 1.15
        float lspeed = 0.35 + 0.45 * L;         // 0.35, 0.8, 1.25
        float alpha = 0.55 + 0.225 * L;         // 0.55, 0.775, 1.0
        float soft = 0.6 + u_shards_depth_blur * (2.0 - L) * 1.6;
        float share = (i == 0) ? 0.45 : ((i == 1) ? 0.33 : 0.22);
        float cell = sqrt(sh_area * 0.75 / max(sh_n * share, 0.5));
        cell = max(cell, sh_smax * scale * 2.6 + 6.0);
        vec4 s = sh_layer(sh_p, L, cell, u_shards_speed * lspeed, scale, alpha * u_shards_opacity, soft,
                          sh_dir, u_shards_spread, u_shards_spin, u_shards_twinkle,
                          sh_smin, sh_smax, u_shards_thin, sh_ncol,
                          u_shards_color, u_shards_color2, u_shards_color3, u_time);
        sh_acc = s + sh_acc * (1.0 - s.a);    // 가까운 겹이 위
    }
}

// 바탕 어둡게 + 조각 얹기 (투명도를 곱한 색끼리)
vec4 sh_base = vec4(sh_orig.rgb * (1.0 - clamp(u_shards_dim, 0.0, 1.0)), sh_orig.a);
vec4 sh_out = sh_acc + sh_base * (1.0 - sh_acc.a);
gl_FragColor = mix(sh_orig, sh_out, clamp(u_shards_strength, 0.0, 1.0));

glsl.fragment_functions:
float sh_hash(vec2 p) {
    p = fract(p * vec2(443.897, 441.423));
    p += dot(p, p.yx + 19.19);
    return fract((p.x + p.y) * p.x);
}

// 조각 하나의 덮는 정도 (0~1). q는 조각 가운데에서 본 자리(픽셀)
// 길쭉한 마름모의 한쪽 끝을 더 뾰족하게: 깨진 유리 조각 같은 모양
float sh_shape(vec2 q, float len, float wid, float soft) {
    float x = q.x / len;
    float w = wid * (x > 0.0 ? (1.0 - x) : (1.0 + x * 1.8));
    float d = max(abs(q.y) - w * len, max(x - 1.0, -0.55 - x) * len);
    return 1.0 - smoothstep(-soft, soft, d);
}

// 한 겹 그리기. 돌려준 값: rgb는 투명도를 곱한 색, a는 덮는 정도
// 효과 유니폼은 함수에서 못 읽어서 다 인자로 받음
vec4 sh_layer(vec2 p, float layer, float cell, float speed, float scale, float alpha, float soft,
              vec2 dirv, float spread, float spin, float twinkle, float smin, float smax, float thin,
              float ncol, vec3 c1, vec3 c2, vec3 c3, float t) {
    // 바람 방향을 x축으로 돌린 자리
    vec2 r = vec2(dot(p, dirv), dot(p, vec2(-dirv.y, dirv.x)));
    r.x -= t * speed;
    vec2 id = floor(r / cell);
    vec2 o = vec2(layer * 17.31, layer * 5.77);

    float h0 = sh_hash(id + o);
    if (h0 > 0.75) return vec4(0.0);        // 칸의 1/4은 비움 (고르게 보이지 않게)

    float h1 = sh_hash(id + o + vec2(1.3, 7.1));
    float h2 = sh_hash(id + o + vec2(9.2, 3.4));
    float h3 = sh_hash(id + o + vec2(4.6, 8.8));
    float h4 = sh_hash(id + o + vec2(7.7, 2.2));

    float sz = mix(smin, smax, h3) * scale;
    float margin = min(sz * 1.2 + 2.0, cell * 0.5);

    // 칸 안 자리 + 흔들림 (칸 밖으로 나가지 않게)
    vec2 c = margin + vec2(h1, h2) * max(cell - 2.0 * margin, 0.0);
    float sway = (cell * 0.5 - margin) * spread;
    c.y += sin(t * (0.8 + h4 * 1.7) + h1 * 6.283) * sway;
    c.x += cos(t * (0.6 + h2 * 1.3) + h3 * 6.283) * sway * 0.5;
    vec2 q = r - (id * cell + c);

    // 돌기 + 판처럼 뒤집힘
    float an = h4 * 6.283 + t * spin * (h1 - 0.5) * 4.0;
    float ca = cos(an);
    float sa = sin(an);
    q = vec2(ca * q.x + sa * q.y, -sa * q.x + ca * q.y);
    float flip = abs(cos(t * spin * (0.7 + h2) + h3 * 6.283));
    float wid = thin * max(flip, 0.15);

    float cov = sh_shape(q, sz, wid, soft);
    if (cov <= 0.0) return vec4(0.0);

    // 색 고르기
    float pick = floor(h2 * ncol);
    vec3 col = pick < 0.5 ? c1 : (pick < 1.5 ? c2 : c3);
    // 비스듬히 비친 빛 (뒤집힐 때 반짝)
    col *= 0.75 + 0.5 * flip * (0.6 + 0.4 * h1);

    float tw = 1.0 - twinkle * (0.5 + 0.5 * sin(t * (3.0 + h0 * 9.0) + h3 * 6.283));
    float a = cov * alpha * tw;
    return vec4(col * a, a);
}

glsl.variables:
uniform sampler2D tex0;
uniform float u_lod_bias;
uniform float u_time;
uniform vec2 u_model_size;
attribute vec2 a_tex_coord;
varying vec2 v_tex_coord;

uniform float u_shards_strength;
uniform float u_shards_count;
uniform float u_shards_colors;
uniform vec3 u_shards_color;
uniform vec3 u_shards_color2;
uniform vec3 u_shards_color3;
uniform float u_shards_opacity;
uniform float u_shards_dim;
uniform float u_shards_size_min;
uniform float u_shards_size_max;
uniform float u_shards_thin;
uniform float u_shards_speed;
uniform float u_shards_direction;
uniform float u_shards_spread;
uniform float u_shards_spin;
uniform float u_shards_twinkle;
uniform float u_shards_depth_blur;

fragment:
vec2 rp_size = max(u_model_size, vec2(1.0));
vec4 rp_orig = texture2D(tex0, v_tex_coord, u_lod_bias);
vec2 rp_p = v_tex_coord * rp_size / max(u_ripple_scale, 1.0);
float rp_t = u_time * u_ripple_speed;

float rp_e = 0.08;
float rp_h = rp_height(rp_p, rp_t, u_ripple_flow);
vec2 rp_grad = vec2(rp_height(rp_p + vec2(rp_e, 0.0), rp_t, u_ripple_flow) - rp_h,
                    rp_height(rp_p + vec2(0.0, rp_e), rp_t, u_ripple_flow) - rp_h) / rp_e;

// 가장자리가 늘어나 보이지 않도록 살짝 확대한 뒤 굴절
vec2 rp_margin = vec2(u_ripple_amount * 1.5) / rp_size;
vec2 rp_uv = 0.5 + (v_tex_coord - 0.5) * (1.0 - 2.0 * rp_margin);
rp_uv += rp_grad * u_ripple_amount / rp_size;
rp_uv = clamp(rp_uv, vec2(0.0), vec2(1.0));

vec4 rp_c = texture2D(tex0, rp_uv, u_lod_bias);

// 액체 표면에 비친 빛 (투명도를 곱한 색이라 a를 곱해서 더함)
vec3 rp_n = normalize(vec3(-rp_grad, 1.0));
float rp_spec = pow(max(0.0, dot(rp_n, normalize(vec3(-0.4, -0.6, 0.7)))), 24.0);
rp_c.rgb = min(rp_c.rgb + rp_c.a * u_ripple_shine * rp_spec, vec3(rp_c.a));

gl_FragColor = mix(rp_orig, rp_c, clamp(u_ripple_strength, 0.0, 1.0));

glsl.fragment_functions:
float rp_hash(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

float rp_noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    vec2 u = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);
    return mix(mix(rp_hash(i), rp_hash(i + vec2(1.0, 0.0)), u.x),
               mix(rp_hash(i + vec2(0.0, 1.0)), rp_hash(i + vec2(1.0, 1.0)), u.x), u.y);
}

float rp_fbm(vec2 p) {
    float v = 0.0;
    float a = 0.5;
    for (int k = 0; k < 2; k++) {
        v += a * rp_noise(p);
        p = p * 2.03 + vec2(1.7, 9.2);
        a *= 0.5;
    }
    return v;
}

float rp_height(vec2 p, float t, float flow) {
    vec2 q = vec2(rp_fbm(p + vec2(0.0, t * 0.30)),
                  rp_fbm(p + vec2(5.2, 1.3) - vec2(t * 0.25, 0.0)));
    return rp_fbm(p + flow * q + vec2(t * 0.10, -t * 0.07));
}

glsl.variables:
uniform sampler2D tex0;
uniform float u_lod_bias;
uniform float u_time;
uniform vec2 u_model_size;
attribute vec2 a_tex_coord;
varying vec2 v_tex_coord;

uniform float u_ripple_strength;
uniform float u_ripple_amount;
uniform float u_ripple_scale;
uniform float u_ripple_speed;
uniform float u_ripple_flow;
uniform float u_ripple_shine;

fragment:
vec2 wv_size = max(u_model_size, vec2(1.0));
vec4 wv_orig = texture2D(tex0, v_tex_coord, u_lod_bias);
vec2 wv_p = v_tex_coord * wv_size;
float wv_w = max(u_waves_wavelength, 2.0);
float wv_diag = length(wv_size);

// ── 1. 가운데 물결 ──
vec2 wv_c = vec2(u_waves_center_x, u_waves_center_y) * wv_size;
vec2 wv_v = wv_p - wv_c;
float wv_d = length(wv_v);
vec2 wv_dir = wv_d > 0.001 ? wv_v / wv_d : vec2(0.0);
float wv_fall = exp(-u_waves_decay * wv_d / wv_diag * 2.0);
float wv_s = 0.0;
if (u_waves_pulse <= 0.0) {
    wv_s = cos(6.28318 * (wv_d - u_time * u_waves_speed) / wv_w) * smoothstep(0.0, wv_w, wv_d);
} else {
    float wv_len = wv_w * max(u_waves_rings, 1.0);
    for (int k = 0; k < 4; k++) {
        float wv_age = mod(u_time, u_waves_pulse) + float(k) * u_waves_pulse;
        float wv_r = wv_age * u_waves_speed;
        wv_s += wv_ring(wv_d, wv_r, wv_len, wv_w);
    }
}
vec2 wv_off = wv_dir * wv_s * wv_fall;
float wv_h = wv_s * wv_fall;

// ── 2. 빗방울: 칸마다 정해진 때에 한 번씩 ──
if (u_waves_drops > 0.0) {
    float wv_cs = 260.0 * max(u_waves_drop_size, 0.1);
    float wv_life = 1.6 * max(u_waves_drop_size, 0.1);
    vec2 wv_base = floor(wv_p / wv_cs - 0.5);
    for (int j = 0; j < 4; j++) {
        vec2 wv_cell = wv_base + vec2(mod(float(j), 2.0), floor(float(j) / 2.0));
        float wv_ph = wv_hash(wv_cell + 3.1);
        float wv_tt = u_time / wv_life + wv_ph;
        float wv_n = floor(wv_tt);
        float wv_age = fract(wv_tt) * wv_life;
        if (wv_hash(wv_cell + wv_n * 7.7) < u_waves_drops) {
            vec2 wv_dc = (wv_cell + vec2(wv_hash(wv_cell + wv_n), wv_hash(wv_cell - wv_n + 1.3))) * wv_cs;
            vec2 wv_dv = wv_p - wv_dc;
            float wv_dd = length(wv_dv);
            float wv_rs = wv_ring(wv_dd, wv_age * u_waves_speed * 0.6, wv_w * 0.6 * 3.0, wv_w * 0.6);
            float wv_fade = 1.0 - wv_age / wv_life;
            wv_rs *= wv_fade * wv_fade * 0.7;
            wv_off += (wv_dd > 0.001 ? wv_dv / wv_dd : vec2(0.0)) * wv_rs;
            wv_h += wv_rs;
        }
    }
}

// ── 3. 굴절 (가장자리가 비지 않게 살짝 확대) ──
vec2 wv_margin = vec2(u_waves_amount) / wv_size;
vec2 wv_uv = 0.5 + (v_tex_coord - 0.5) * (1.0 - 2.0 * wv_margin);
wv_uv = clamp(wv_uv - wv_off * u_waves_amount / wv_size, vec2(0.0), vec2(1.0));
vec4 wv_col = texture2D(tex0, wv_uv, u_lod_bias);

// ── 4. 물결 등성이에 비친 빛 (투명도를 곱한 색이라 a를 곱해서 더함) ──
float wv_spec = pow(max(wv_h, 0.0), 3.0) * u_waves_shine;
wv_col.rgb = min(wv_col.rgb + wv_col.a * wv_spec * 0.6, vec3(wv_col.a));

gl_FragColor = mix(wv_orig, wv_col, clamp(u_waves_strength, 0.0, 1.0));

glsl.fragment_functions:
float wv_hash(vec2 p) {
    return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453);
}

// 물결 하나의 기울기: d = 가운데에서 거리, r = 앞머리 반지름, len = 물결 띠 길이, w = 물결 간격
float wv_ring(float d, float r, float len, float w) {
    float x = r - d;
    if (x < 0.0 || x > len) {
        return 0.0;
    }
    float env = sin(3.14159 * x / len);
    return cos(6.28318 * x / w) * env;
}

glsl.variables:
uniform sampler2D tex0;
uniform float u_lod_bias;
uniform float u_time;
uniform vec2 u_model_size;
attribute vec2 a_tex_coord;
varying vec2 v_tex_coord;

uniform float u_waves_strength;
uniform float u_waves_center_x;
uniform float u_waves_center_y;
uniform float u_waves_amount;
uniform float u_waves_wavelength;
uniform float u_waves_speed;
uniform float u_waves_decay;
uniform float u_waves_pulse;
uniform float u_waves_rings;
uniform float u_waves_drops;
uniform float u_waves_drop_size;
uniform float u_waves_shine;

fragment:
vec2 cl_size = max(u_model_size, vec2(1.0));
vec2 cl_p = v_tex_coord * cl_size;
vec4 cl_orig = texture2D(tex0, v_tex_coord, u_lod_bias);

float cl_n = clamp(floor(u_collage_count + 0.5), 0.0, 10.0);
float cl_area = clamp(u_collage_area, 0.05, 1.0);
float cl_smin = clamp(min(u_collage_size_min, u_collage_size_max), 0.02, 1.0);
float cl_smax = clamp(max(u_collage_size_min, u_collage_size_max), 0.02, 1.0);
float cl_lw = max(u_collage_line_width, 0.0);
float cl_sw = 3.0 + cl_lw * 2.0;                       // 그림자 폭 (픽셀)
vec2 cl_sh = vec2(1.0, 1.5) * (1.0 + cl_lw);           // 그림자는 오른쪽 아래로

vec4 cl_out = cl_orig;
for (int i = 0; i < 10; i++) {
    float fi = float(i);
    if (fi < cl_n) {
        // 조각마다 다른 때에 바뀜: 바꾸기 간격도, 시작 때도 조각마다 다름
        float ph = cl_hash(vec2(fi, 9.1));
        float per = u_collage_shuffle * mix(0.7, 1.6, cl_hash(vec2(fi, 5.3)));
        float ep = (u_collage_shuffle > 0.0) ? floor(u_time / per + ph) : 0.0;
        vec2 s = vec2(fi * 7.13 + ep * 0.371, ep * 1.913 + fi * 0.57);
        vec4 r = cl_piece(s, cl_size, cl_area, cl_smin, cl_smax, u_collage_strips);
        float d = cl_inside(cl_p, r);

        if (d >= 0.0) {
            // 같은 장면을 다시 찍은 것처럼: 조금 밀리고 조금 확대
            vec2 ctr = r.xy + r.zw * 0.5;
            vec2 off = (vec2(cl_hash(s + 0.11), cl_hash(s + 0.37)) - 0.5) * 2.0 * u_collage_offset;
            float z = 1.0 + u_collage_zoom * cl_hash(s + 0.59);
            vec4 c = cl_read(tex0, ctr + (cl_p - ctr) / z + off, cl_size);
            float a = c.a;
            vec3 col = (a > 0.0001) ? c.rgb / a : vec3(0.0);

            col *= 1.0 + (cl_hash(s + 0.83) - 0.5) * 2.0 * u_collage_shade;
            if (cl_hash(s + 2.3) < u_collage_tint_amount) {
                float l = dot(col, vec3(0.299, 0.587, 0.114));
                col = mix(col, u_collage_tint * (0.3 + l * 1.1), 0.35);
            }

            // 가는 테두리 (조각 안쪽 가장자리)
            float ln = (1.0 - smoothstep(cl_lw - 0.5, cl_lw + 0.5, d)) * u_collage_lines;
            col = mix(col, u_collage_line_color, ln);
            a = max(a, ln * cl_orig.a);
            cl_out = vec4(clamp(col, 0.0, 1.0) * a, a);
        }
        else {
            // 아래에 깔린 것에 옅은 그림자
            float ds = -cl_inside(cl_p - cl_sh, r);
            float sd = (ds <= 0.0) ? 1.0 : (1.0 - smoothstep(0.0, cl_sw, ds));
            cl_out.rgb *= 1.0 - u_collage_shadow * 0.5 * sd;
        }
    }
}

gl_FragColor = mix(cl_orig, cl_out, clamp(u_collage_strength, 0.0, 1.0));

glsl.fragment_functions:
float cl_hash(vec2 p) {
    p = fract(p * vec2(443.897, 441.423));
    p += dot(p, p.yx + 19.19);
    return fract((p.x + p.y) * p.x);
}

vec4 cl_read(sampler2D t, vec2 px, vec2 size) {
    vec2 lo = 0.5 / size;
    return texture2D(t, clamp(px / size, lo, 1.0 - lo));
}

// 네모 테두리까지의 거리 (픽셀). 안이면 +, 밖이면 -
float cl_inside(vec2 p, vec4 r) {
    vec2 e = min(p - r.xy, r.xy + r.zw - p);
    return min(e.x, e.y);
}

// 조각 i의 (왼쪽 위 x, y, 가로, 세로) 픽셀. s = 조각과 그 조각의 바뀐 횟수로 만든 씨앗
// 효과 유니폼은 함수에서 못 읽어서 인자로 받음
vec4 cl_piece(vec2 s, vec2 size, float area, float smin, float smax, float strips) {
    vec2 box = size * area;
    vec2 bo = (size - box) * 0.5;
    float h1 = cl_hash(s + vec2(0.13, 0.71));
    float h2 = cl_hash(s + vec2(0.57, 0.29));
    float h3 = cl_hash(s + vec2(0.91, 0.43));
    float h4 = cl_hash(s + vec2(0.37, 0.83));
    vec2 wh = box * vec2(mix(smin, smax, h1), mix(smin, smax, h2));
    if (h3 < strips) {
        // 가는 띠: 한쪽은 가늘게, 다른 쪽은 길게
        float thin = mix(0.03, 0.08, h4);
        float lng = mix(0.35, 0.8, h1);
        wh = (h4 < 0.5) ? box * vec2(lng, thin) : box * vec2(thin, lng);
    }
    wh = min(wh, box);
    // 가운데에 몰리게 (해시 둘의 평균)
    vec2 c = vec2(cl_hash(s + vec2(1.7, 0.3)) + cl_hash(s + vec2(2.9, 1.1)),
                  cl_hash(s + vec2(0.5, 3.7)) + cl_hash(s + vec2(4.1, 2.3))) * 0.5;
    return vec4(bo + c * (box - wh), wh);
}

// 타일 전환용 칸: 기본 칸 g를 3×2개씩 묶고 묶음마다 여덟 가지 나눔 중 하나
vec4 cl_grid(vec2 p, float g) {
    vec2 ms = vec2(3.0, 2.0) * g;
    vec2 m = floor(p / ms);
    vec2 lc = floor((p - m * ms) / g);
    float pat = floor(cl_hash(m) * 8.0);
    vec4 r;
    if (pat < 0.5) r = vec4(0.0, 0.0, 3.0, 2.0);
    else if (pat < 1.5) r = (lc.x < 1.5) ? vec4(0.0, 0.0, 2.0, 2.0) : vec4(2.0, 0.0, 1.0, 2.0);
    else if (pat < 2.5) r = (lc.x < 0.5) ? vec4(0.0, 0.0, 1.0, 2.0) : vec4(1.0, 0.0, 2.0, 2.0);
    else if (pat < 3.5) r = vec4(lc.x, 0.0, 1.0, 2.0);
    else if (pat < 4.5) r = vec4(0.0, lc.y, 3.0, 1.0);
    else if (pat < 5.5) {
        if (lc.y < 0.5) r = (lc.x < 1.5) ? vec4(0.0, 0.0, 2.0, 1.0) : vec4(2.0, 0.0, 1.0, 1.0);
        else r = (lc.x < 0.5) ? vec4(0.0, 1.0, 1.0, 1.0) : vec4(1.0, 1.0, 2.0, 1.0);
    }
    else if (pat < 6.5) r = vec4(lc, 1.0, 1.0);
    else r = (lc.x < 1.5) ? vec4(0.0, 0.0, 2.0, 2.0) : vec4(2.0, lc.y, 1.0, 1.0);
    return vec4(m * ms + r.xy * g, r.zw * g);
}

glsl.variables:
uniform sampler2D tex0;
uniform float u_lod_bias;
uniform float u_time;
uniform vec2 u_model_size;
attribute vec2 a_tex_coord;
varying vec2 v_tex_coord;

uniform float u_collage_strength;
uniform float u_collage_count;
uniform float u_collage_area;
uniform float u_collage_size_min;
uniform float u_collage_size_max;
uniform float u_collage_strips;
uniform float u_collage_shuffle;
uniform float u_collage_offset;
uniform float u_collage_zoom;
uniform float u_collage_shade;
uniform vec3 u_collage_tint;
uniform float u_collage_tint_amount;
uniform float u_collage_lines;
uniform float u_collage_line_width;
uniform vec3 u_collage_line_color;
uniform float u_collage_shadow;

fragment:
vec2 wb_size = max(u_model_size, vec2(1.0));
vec4 wb_orig = texture2D(tex0, v_tex_coord, u_lod_bias);
vec2 wb_p = v_tex_coord * wb_size;

float wb_t = u_time;
if (u_wobble_fps > 0.5) {
    wb_t = floor(u_time * u_wobble_fps) / u_wobble_fps;
}
float wb_flow = wb_t * u_wobble_speed;

vec2 wb_q = wb_p / vec2(max(u_wobble_size_x, 1.0), max(u_wobble_size_y, 1.0));
wb_q.y += wb_t * u_wobble_rise;
vec2 wb_d = vec2(wb_turb(wb_q + vec2(wb_flow, 0.0), u_wobble_detail),
                 wb_turb(wb_q + vec2(17.3, 9.1) - vec2(0.0, wb_flow), u_wobble_detail));

// 세기 출렁임: 천천히 세졌다 약해졌다
float wb_amp = u_wobble_amount * (1.0 - u_wobble_pulse * (0.5 + 0.5 * sin(u_time * u_wobble_pulse_speed * 6.28318)));

// 가장자리가 비지 않게 살짝 확대
vec2 wb_margin = vec2(u_wobble_amount) / wb_size;
vec2 wb_uv = 0.5 + (v_tex_coord - 0.5) * (1.0 - 2.0 * wb_margin);
wb_uv = clamp(wb_uv + wb_d * wb_amp / wb_size, vec2(0.0), vec2(1.0));

vec4 wb_col = texture2D(tex0, wb_uv, u_lod_bias);
gl_FragColor = mix(wb_orig, wb_col, clamp(u_wobble_strength, 0.0, 1.0));

glsl.fragment_functions:
vec2 wb_grad(vec2 p) {
    float a = fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453) * 6.28318;
    return vec2(cos(a), sin(a));
}

// 펄린 노이즈 (-1 ~ 1 근처)
float wb_perlin(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    vec2 u = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);
    float a = dot(wb_grad(i), f);
    float b = dot(wb_grad(i + vec2(1.0, 0.0)), f - vec2(1.0, 0.0));
    float c = dot(wb_grad(i + vec2(0.0, 1.0)), f - vec2(0.0, 1.0));
    float d = dot(wb_grad(i + vec2(1.0, 1.0)), f - vec2(1.0, 1.0));
    return mix(mix(a, b, u.x), mix(c, d, u.x), u.y) * 1.4;
}

float wb_turb(vec2 p, float detail) {
    return wb_perlin(p) + detail * 0.5 * wb_perlin(p * 2.1 + vec2(3.7, 1.9)) + detail * 0.25 * wb_perlin(p * 4.3 + vec2(8.1, 5.3));
}

glsl.variables:
uniform sampler2D tex0;
uniform float u_lod_bias;
uniform float u_time;
uniform vec2 u_model_size;
attribute vec2 a_tex_coord;
varying vec2 v_tex_coord;

uniform float u_wobble_strength;
uniform float u_wobble_amount;
uniform float u_wobble_size_x;
uniform float u_wobble_size_y;
uniform float u_wobble_detail;
uniform float u_wobble_speed;
uniform float u_wobble_pulse;
uniform float u_wobble_pulse_speed;
uniform float u_wobble_rise;
uniform float u_wobble_fps;

fragment:
vec2 fg_size = max(u_model_size, vec2(1.0));
vec4 fg_orig = texture2D(tex0, v_tex_coord, u_lod_bias);
float fg_f = floor(u_time * max(u_filmgrain_fps, 1.0));

// ── 1. 덜컹거림: 필름이 프레임마다 조금씩 밀림 ──
vec2 fg_wv = vec2(fg_hash1(fg_f) - 0.5, fg_hash1(fg_f + 7.1) - 0.5) * u_filmgrain_weave;
fg_wv.y += (fg_hash1(floor(fg_f / 9.0)) > 0.93 ? 1.0 : 0.0) * u_filmgrain_weave * 2.0;
vec2 fg_margin = vec2(u_filmgrain_weave * 1.5) / fg_size;
vec2 fg_uv = 0.5 + (v_tex_coord - 0.5) * (1.0 - 2.0 * fg_margin) + fg_wv / fg_size;
vec4 fg_c = texture2D(tex0, clamp(fg_uv, vec2(0.0), vec2(1.0)), u_lod_bias);
float fg_a = fg_c.a;
vec3 fg_rgb = fg_a > 0.001 ? fg_c.rgb / fg_a : vec3(0.0);
vec2 fg_p = v_tex_coord * fg_size;

// ── 2. 바랜 색과 물드는 색 ──
float fg_l = dot(fg_rgb, vec3(0.299, 0.587, 0.114));
fg_rgb = mix(fg_rgb, vec3(fg_l), u_filmgrain_fade);
fg_rgb = mix(fg_rgb, fg_rgb * u_filmgrain_tint * 1.15, u_filmgrain_tint_amount);
fg_rgb = mix(fg_rgb, vec3(0.5), u_filmgrain_fade * 0.15);

// ── 3. 밝기 깜빡임 ──
fg_rgb *= 1.0 + (fg_hash1(fg_f + 3.3) - 0.5) * 2.0 * u_filmgrain_flicker;

// ── 4. 입자 ──
vec2 fg_g = floor(fg_p / max(u_filmgrain_grain_size, 1.0));
float fg_n = fg_hash(fg_g + vec2(fg_f * 13.17, fg_f * 7.31)) + fg_hash(fg_g * 1.37 + vec2(fg_f * 3.1, 1.7)) - 1.0;
fg_rgb += fg_n * u_filmgrain_grain * (0.6 + 0.4 * (1.0 - fg_l));

// ── 5. 먼지 점: 칸마다 이 프레임에 먼지가 있을지 ──
float fg_dust = 0.0;
float fg_dsign = 1.0;
if (u_filmgrain_dust > 0.0) {
    float fg_cs = 46.0;
    vec2 fg_cell = floor(fg_p / fg_cs);
    float fg_hh = fg_hash(fg_cell + fg_f * 1.731);
    if (fg_hh < u_filmgrain_dust * 0.06) {
        vec2 fg_pos = (fg_cell + vec2(fg_hash(fg_cell + fg_f), fg_hash(fg_cell - fg_f + 4.1)) * 0.7 + 0.15) * fg_cs;
        float fg_r = 0.8 + fg_hash(fg_cell * 2.3 + fg_f) * 3.2;
        vec2 fg_dv = (fg_p - fg_pos) * vec2(1.0, 0.7 + fg_hash(fg_cell + 9.0 + fg_f) * 0.6);
        fg_dust = 1.0 - smoothstep(fg_r * 0.6, fg_r, length(fg_dv));
        fg_dsign = fg_hash(fg_cell + fg_f * 3.0 + 2.0) < u_filmgrain_dark_dust ? -1.0 : 1.0;
    }
}

// ── 6. 세로 긁힘: 몇 초씩 같은 자리에 머물며 조금씩 떨림 ──
float fg_scr = 0.0;
if (u_filmgrain_scratches > 0.0) {
    for (int k = 0; k < 3; k++) {
        float fg_k = float(k);
        float fg_seg = floor(u_time * (0.4 + fg_k * 0.23) + fg_k * 5.0);
        if (fg_hash1(fg_seg * 3.7 + fg_k) < u_filmgrain_scratches * 0.9) {
            float fg_x = fg_hash1(fg_seg + fg_k * 11.0) * fg_size.x + (fg_hash1(fg_f + fg_k) - 0.5) * 3.0;
            float fg_w = 0.6 + fg_hash1(fg_seg * 1.3 + fg_k) * 1.2;
            float fg_y0 = fg_hash1(fg_seg * 2.1 + fg_k) * 0.6 - 0.2;
            float fg_y1 = fg_y0 + 0.4 + fg_hash1(fg_seg * 4.9 + fg_k) * 0.8;
            float fg_on = step(fg_y0, v_tex_coord.y) * step(v_tex_coord.y, fg_y1);
            float fg_bright = 0.35 + 0.65 * fg_hash(vec2(floor(fg_p.y / 6.0), fg_f + fg_k));
            fg_scr = max(fg_scr, (1.0 - smoothstep(fg_w * 0.5, fg_w, abs(fg_p.x - fg_x))) * fg_on * fg_bright);
        }
    }
}

// ── 7. 머리카락: 가끔 한 프레임씩 꼬불꼬불한 선 ──
float fg_hair = 0.0;
if (u_filmgrain_hair > 0.0) {
    float fg_hs = floor(u_time * 1.3);
    if (fg_hash1(fg_hs * 5.3) < u_filmgrain_hair * 0.6 && fg_hash1(fg_f * 1.9) < 0.75) {
        vec2 fg_hc = vec2(fg_hash1(fg_hs + 1.0), fg_hash1(fg_hs + 2.0)) * fg_size;
        vec2 fg_hp = fg_p - fg_hc;
        float fg_ang = fg_hash1(fg_hs + 3.0) * 6.28318;
        vec2 fg_hr = vec2(cos(fg_ang) * fg_hp.x + sin(fg_ang) * fg_hp.y, -sin(fg_ang) * fg_hp.x + cos(fg_ang) * fg_hp.y);
        float fg_len = 60.0 + fg_hash1(fg_hs + 4.0) * 120.0;
        float fg_curve = sin(fg_hr.x * 0.045 + fg_hs) * 18.0 + sin(fg_hr.x * 0.11 + fg_hs * 2.0) * 7.0;
        float fg_hd = abs(fg_hr.y - fg_curve);
        fg_hair = (1.0 - smoothstep(0.5, 1.4, fg_hd)) * (1.0 - smoothstep(fg_len * 0.8, fg_len, abs(fg_hr.x)));
    }
}

fg_rgb += fg_dust * fg_dsign * 0.8;
fg_rgb += fg_scr * 0.45;
fg_rgb -= fg_hair * 0.55;

// ── 8. 가장자리 어둡게 ──
vec2 fg_vc = v_tex_coord - 0.5;
fg_rgb *= 1.0 - u_filmgrain_vignette * smoothstep(0.15, 0.75, length(fg_vc * vec2(1.0, 0.85)) * 1.25);

vec4 fg_out = vec4(clamp(fg_rgb, 0.0, 1.0) * fg_a, fg_a);
gl_FragColor = mix(fg_orig, fg_out, clamp(u_filmgrain_strength, 0.0, 1.0));

glsl.fragment_functions:
float fg_hash(vec2 p) {
    return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453);
}

float fg_hash1(float n) {
    return fract(sin(n * 91.3458) * 47453.5453);
}

glsl.variables:
uniform sampler2D tex0;
uniform float u_lod_bias;
uniform float u_time;
uniform vec2 u_model_size;
attribute vec2 a_tex_coord;
varying vec2 v_tex_coord;

uniform float u_filmgrain_strength;
uniform float u_filmgrain_fps;
uniform float u_filmgrain_grain;
uniform float u_filmgrain_grain_size;
uniform float u_filmgrain_dust;
uniform float u_filmgrain_scratches;
uniform float u_filmgrain_hair;
uniform float u_filmgrain_flicker;
uniform float u_filmgrain_weave;
uniform float u_filmgrain_vignette;
uniform float u_filmgrain_fade;
uniform vec3 u_filmgrain_tint;
uniform float u_filmgrain_tint_amount;
uniform float u_filmgrain_dark_dust;

fragment:
vec2 fe_size = max(u_model_size, vec2(1.0));
vec4 fe_orig = texture2D(tex0, v_tex_coord, u_lod_bias);
vec2 fe_c = vec2(u_fisheye_center_x, u_fisheye_center_y);
float fe_asp = fe_size.x / fe_size.y;

vec2 fe_v = (v_tex_coord - fe_c) * vec2(fe_asp, 1.0);
float fe_rmax = length(vec2(fe_asp, 1.0) * 0.5);
// 둥근 화면일수록 원의 가장자리가 화면 모서리를 보게 (화면 전체가 원 안에 들어옴)
float fe_circ = clamp(u_fisheye_circle, 0.0, 1.0);
float fe_rn = mix(fe_rmax, 0.5, fe_circ);
float fe_r = length(fe_v) / fe_rn;
float fe_rs = mix(fe_rmax, 0.5, fe_circ);
vec2 fe_dir = fe_r > 0.0001 ? fe_v / (fe_r * fe_rn) : vec2(0.0);

float fe_k = clamp(u_fisheye_amount * (1.0 + u_fisheye_breathe * sin(u_time * 1.7)), 0.0, 1.0);
float fe_z = max(u_fisheye_zoom, 0.05);
float fe_ch = u_fisheye_chroma * 0.06 * fe_r * fe_r;

vec2 fe_ug = fe_c + fe_dir * fe_map(fe_r, fe_k) * fe_rs / fe_z / vec2(fe_asp, 1.0);
vec2 fe_ur = fe_c + fe_dir * fe_map(fe_r * (1.0 + fe_ch), fe_k) * fe_rs / fe_z / vec2(fe_asp, 1.0);
vec2 fe_ub = fe_c + fe_dir * fe_map(fe_r * (1.0 - fe_ch), fe_k) * fe_rs / fe_z / vec2(fe_asp, 1.0);

vec4 fe_g = texture2D(tex0, clamp(fe_ug, vec2(0.0), vec2(1.0)), u_lod_bias);
vec4 fe_rr = texture2D(tex0, clamp(fe_ur, vec2(0.0), vec2(1.0)), u_lod_bias);
vec4 fe_bb = texture2D(tex0, clamp(fe_ub, vec2(0.0), vec2(1.0)), u_lod_bias);
vec4 fe_col = vec4(fe_rr.r, fe_g.g, fe_bb.b, fe_g.a);

// 화면 밖을 읽는 곳은 검게
float fe_out = step(0.0, fe_ug.x) * step(fe_ug.x, 1.0) * step(0.0, fe_ug.y) * step(fe_ug.y, 1.0);
fe_col = mix(vec4(0.0, 0.0, 0.0, 1.0), fe_col, fe_out);

// 가장자리 어둡게
fe_col.rgb *= 1.0 - u_fisheye_vignette * smoothstep(0.35, 1.05, min(fe_r, 1.2));

// 둥근 화면: 짧은 쪽에 맞춘 원 밖을 검게
if (u_fisheye_circle > 0.0) {
    float fe_cr = length((v_tex_coord - fe_c) * vec2(fe_asp, 1.0)) / 0.5;
    float fe_lim = mix(fe_rmax / 0.5 + 0.1, 1.0, fe_circ);
    float fe_m = 1.0 - smoothstep(fe_lim - u_fisheye_circle_soft, fe_lim, fe_cr);
    fe_col = mix(vec4(0.0, 0.0, 0.0, 1.0), fe_col, fe_m);
}

gl_FragColor = mix(fe_orig, fe_col, clamp(u_fisheye_strength, 0.0, 1.0));

glsl.fragment_functions:
// 가운데에서의 거리 r(0 ~ 1 = 모서리)를 읽을 자리의 거리로 바꿈. 가운데는 크게, 가장자리는 눌리게
float fe_map(float r, float k) {
    float a = 0.05 + k * 1.0;
    return tan(r * a) / tan(a);
}

glsl.variables:
uniform sampler2D tex0;
uniform float u_lod_bias;
uniform float u_time;
uniform vec2 u_model_size;
attribute vec2 a_tex_coord;
varying vec2 v_tex_coord;

uniform float u_fisheye_strength;
uniform float u_fisheye_amount;
uniform float u_fisheye_zoom;
uniform float u_fisheye_center_x;
uniform float u_fisheye_center_y;
uniform float u_fisheye_chroma;
uniform float u_fisheye_circle;
uniform float u_fisheye_circle_soft;
uniform float u_fisheye_vignette;
uniform float u_fisheye_breathe;

fragment:
vec2 pc_size = max(u_model_size, vec2(1.0));
vec4 pc_orig = texture2D(tex0, v_tex_coord, u_lod_bias);
vec2 pc_p = v_tex_coord * pc_size;
float pc_f = u_photocopy_fps > 0.5 ? floor(u_time * u_photocopy_fps) : 0.0;
vec2 pc_fo = vec2(fract(pc_f * 0.6180339) * 91.0, fract(pc_f * 0.4142135) * 73.0);

// ── 1. 인쇄 어긋남: 세로로 조금 끌린 두 장을 겹침 ──
vec2 pc_px = vec2(1.0) / pc_size;
float pc_l0 = pc_lum(texture2D(tex0, v_tex_coord, u_lod_bias));
float pc_l1 = pc_lum(texture2D(tex0, clamp(v_tex_coord - vec2(0.0, u_photocopy_smear) * pc_px, vec2(0.0), vec2(1.0)), u_lod_bias));
float pc_l2 = pc_lum(texture2D(tex0, clamp(v_tex_coord + vec2(u_photocopy_smear * 0.5, 0.0) * pc_px, vec2(0.0), vec2(1.0)), u_lod_bias));
float pc_l = min(pc_l0, mix(pc_l1, pc_l2, 0.5) + 0.08);

// ── 2. 토너가 뭉침: 대비를 올리고 몇 단계로 ──
float pc_n = pc_noise(pc_p / 3.0 + pc_fo) - 0.5;
float pc_v = clamp((pc_l - u_photocopy_threshold + pc_n * 0.05) * u_photocopy_contrast + 0.5, 0.0, 1.0);
float pc_lv = max(floor(u_photocopy_levels + 0.5), 1.0);
pc_v = pc_lv <= 1.0 ? step(0.5, pc_v) : floor(pc_v * pc_lv + 0.5) / pc_lv;

// ── 3. 검은 얼룩과 흰 빈 곳 ──
float pc_big = pc_noise(pc_p / 90.0 + pc_fo * 0.3);
float pc_fine = pc_hash(floor(pc_p / 1.5) + pc_fo);
float pc_blot = step(1.0 - u_photocopy_toner * 0.08, pc_fine) * step(0.45, pc_big);
pc_blot = max(pc_blot, step(1.0 - u_photocopy_toner * 0.25, pc_noise(pc_p / 4.0 + pc_fo * 2.0)) * step(0.62, pc_big));
float pc_hole = step(1.0 - u_photocopy_speckle * 0.03, pc_hash(floor(pc_p / 2.0) + pc_fo + 5.0)) * (1.0 - pc_v) * step(0.5, pc_noise(pc_p / 30.0 + pc_fo));
pc_v = clamp(pc_v - pc_blot + pc_hole, 0.0, 1.0);

// ── 4. 세로로 끌린 줄 ──
float pc_col = floor(pc_p.x / 2.0);
float pc_st = pc_hash(vec2(pc_col, floor(pc_f / 6.0)));
float pc_line = step(1.0 - u_photocopy_streaks * 0.04, pc_st) * (0.5 + 0.5 * pc_noise(vec2(pc_col, pc_p.y / 40.0 + pc_fo.x)));
pc_v = clamp(pc_v - pc_line * 0.7, 0.0, 1.0);

// ── 5. 가장자리 그림자 (복사기 뚜껑 틈) ──
vec2 pc_e = min(v_tex_coord, 1.0 - v_tex_coord);
float pc_edge = 1.0 - smoothstep(0.0, 0.06, min(pc_e.x * pc_size.x / pc_size.y, pc_e.y));
pc_v *= 1.0 - u_photocopy_edge * pc_edge * (0.6 + 0.4 * pc_noise(pc_p / 12.0));

vec3 pc_rgb = mix(u_photocopy_ink, u_photocopy_paper, pc_v);
vec4 pc_out = vec4(pc_rgb * pc_orig.a, pc_orig.a);
gl_FragColor = mix(pc_orig, pc_out, clamp(u_photocopy_strength, 0.0, 1.0));

glsl.fragment_functions:
float pc_hash(vec2 p) {
    return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453);
}

float pc_noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    vec2 u = f * f * (3.0 - 2.0 * f);
    return mix(mix(pc_hash(i), pc_hash(i + vec2(1.0, 0.0)), u.x),
               mix(pc_hash(i + vec2(0.0, 1.0)), pc_hash(i + vec2(1.0, 1.0)), u.x), u.y);
}

float pc_lum(vec4 c) {
    vec3 rgb = c.a > 0.001 ? c.rgb / c.a : vec3(0.0);
    return dot(rgb, vec3(0.299, 0.587, 0.114));
}

glsl.variables:
uniform sampler2D tex0;
uniform float u_lod_bias;
uniform float u_time;
uniform vec2 u_model_size;
attribute vec2 a_tex_coord;
varying vec2 v_tex_coord;

uniform float u_photocopy_strength;
uniform float u_photocopy_threshold;
uniform float u_photocopy_contrast;
uniform float u_photocopy_levels;
uniform float u_photocopy_toner;
uniform float u_photocopy_speckle;
uniform float u_photocopy_streaks;
uniform float u_photocopy_smear;
uniform vec3 u_photocopy_paper;
uniform vec3 u_photocopy_ink;
uniform float u_photocopy_edge;
uniform float u_photocopy_fps;

fragment:
vec2 rl_size = max(u_model_size, vec2(1.0));
vec4 rl_orig = texture2D(tex0, v_tex_coord, u_lod_bias);
vec2 rl_o = vec2(max(u_relief_radius, 0.5)) / rl_size;

// ── 1. 밝기 기울기 (소벨) ──
float rl_tl = rl_lum(v_tex_coord + vec2(-rl_o.x, -rl_o.y));
float rl_t = rl_lum(v_tex_coord + vec2(0.0, -rl_o.y));
float rl_tr = rl_lum(v_tex_coord + vec2(rl_o.x, -rl_o.y));
float rl_l = rl_lum(v_tex_coord + vec2(-rl_o.x, 0.0));
float rl_r = rl_lum(v_tex_coord + vec2(rl_o.x, 0.0));
float rl_bl = rl_lum(v_tex_coord + vec2(-rl_o.x, rl_o.y));
float rl_b = rl_lum(v_tex_coord + vec2(0.0, rl_o.y));
float rl_br = rl_lum(v_tex_coord + vec2(rl_o.x, rl_o.y));
vec2 rl_g = vec2((rl_tr + 2.0 * rl_r + rl_br) - (rl_tl + 2.0 * rl_l + rl_bl),
                 (rl_bl + 2.0 * rl_b + rl_br) - (rl_tl + 2.0 * rl_t + rl_tr));
if (u_relief_invert > 0.5) {
    rl_g = -rl_g;
}

// ── 2. 빛 ──
vec3 rl_n = normalize(vec3(-rl_g * u_relief_depth, 1.0));
float rl_a = radians(u_relief_angle + u_time * u_relief_sweep * 60.0);
vec3 rl_ld = normalize(vec3(cos(rl_a), -sin(rl_a), 0.8));
float rl_diff = max(dot(rl_n, rl_ld), 0.0);
vec3 rl_h = normalize(rl_ld + vec3(0.0, 0.0, 1.0));
float rl_spec = pow(max(dot(rl_n, rl_h), 0.0), max(u_relief_gloss, 1.0)) * u_relief_shine;

// ── 3. 판 색 (원래 색을 조금 남길 수 있음) ──
vec3 rl_src = rl_orig.a > 0.001 ? rl_orig.rgb / rl_orig.a : vec3(0.0);
vec3 rl_base = mix(u_relief_metal, rl_src, clamp(u_relief_color, 0.0, 1.0));
vec3 rl_rgb = rl_base * (0.35 + 0.75 * rl_diff) + vec3(rl_spec) * mix(vec3(1.0), u_relief_metal, 0.4);

vec4 rl_out = vec4(clamp(rl_rgb, 0.0, 1.0) * rl_orig.a, rl_orig.a);
gl_FragColor = mix(rl_orig, rl_out, clamp(u_relief_strength, 0.0, 1.0));

glsl.fragment_functions:
float rl_lum(vec2 uv) {
    vec4 c = texture2D(tex0, clamp(uv, vec2(0.0), vec2(1.0)));
    vec3 rgb = c.a > 0.001 ? c.rgb / c.a : vec3(0.0);
    return dot(rgb, vec3(0.299, 0.587, 0.114));
}

glsl.variables:
uniform sampler2D tex0;
uniform float u_lod_bias;
uniform float u_time;
uniform vec2 u_model_size;
attribute vec2 a_tex_coord;
varying vec2 v_tex_coord;

uniform float u_relief_strength;
uniform float u_relief_depth;
uniform float u_relief_radius;
uniform float u_relief_angle;
uniform vec3 u_relief_metal;
uniform float u_relief_color;
uniform float u_relief_shine;
uniform float u_relief_gloss;
uniform float u_relief_invert;
uniform float u_relief_sweep;

fragment:
vec2 gm_size = max(u_model_size, vec2(1.0));
vec4 gm_orig = texture2D(tex0, v_tex_coord, u_lod_bias);
vec3 gm_rgb = gm_orig.a > 0.001 ? gm_orig.rgb / gm_orig.a : vec3(0.0);

float gm_l = dot(gm_rgb, vec3(0.2126, 0.7152, 0.0722));
gm_l = clamp(((gm_l - 0.5) * u_gradmap_contrast + 0.5) * u_gradmap_brightness, 0.0, 1.0);
if (u_gradmap_shift > 0.0) {
    gm_l = fract(gm_l + u_time * u_gradmap_shift * 0.2);
}

float gm_n = floor(u_gradmap_levels + 0.5);
if (gm_n >= 1.0) {
    float gm_d = (gm_bayer(v_tex_coord * gm_size) - 0.5) * u_gradmap_dither;
    gm_l = clamp(floor(gm_l * gm_n + 0.5 + gm_d) / gm_n, 0.0, 1.0);
}

float gm_m = clamp(u_gradmap_mid_pos, 0.01, 0.99);
vec3 gm_col = gm_l < gm_m
    ? mix(u_gradmap_shadow, u_gradmap_mid, gm_l / gm_m)
    : mix(u_gradmap_mid, u_gradmap_light, (gm_l - gm_m) / (1.0 - gm_m));

vec4 gm_out = vec4(gm_col * gm_orig.a, gm_orig.a);
gl_FragColor = mix(gm_orig, gm_out, clamp(u_gradmap_strength, 0.0, 1.0));

glsl.fragment_functions:
// 4x4 바이어 행렬 값 (0 ~ 1)
float gm_bayer(vec2 p) {
    vec2 q = mod(floor(p), 4.0);
    float a = mod(q.x, 2.0);
    float b = mod(q.y, 2.0);
    float c = mod(floor(q.x / 2.0), 2.0);
    float d = mod(floor(q.y / 2.0), 2.0);
    float v = 8.0 * mod(a + b, 2.0) + 4.0 * b + 2.0 * mod(c + d, 2.0) + d;
    return (v + 0.5) / 16.0;
}

glsl.variables:
uniform sampler2D tex0;
uniform float u_lod_bias;
uniform float u_time;
uniform vec2 u_model_size;
attribute vec2 a_tex_coord;
varying vec2 v_tex_coord;

uniform float u_gradmap_strength;
uniform vec3 u_gradmap_shadow;
uniform vec3 u_gradmap_mid;
uniform vec3 u_gradmap_light;
uniform float u_gradmap_mid_pos;
uniform float u_gradmap_brightness;
uniform float u_gradmap_contrast;
uniform float u_gradmap_levels;
uniform float u_gradmap_dither;
uniform float u_gradmap_shift;

fragment:
vec2 rg_size = max(u_model_size, vec2(1.0));
vec4 rg_orig = texture2D(tex0, v_tex_coord, u_lod_bias);
vec2 rg_c = vec2(u_rings_center_x, u_rings_center_y) * rg_size;
vec2 rg_v = v_tex_coord * rg_size - rg_c;
float rg_d = length(rg_v);
float rg_w = max(u_rings_width, 2.0);
float rg_i = floor(rg_d / rg_w);

// 반으로 가르면 위쪽, 아래쪽이 다른 고리처럼 움직임
float rg_side = 0.0;
if (u_rings_halves > 0.5) {
    float rg_ang0 = 0.7 + rg_hash(rg_i + 40.0) * 1.5;
    rg_side = step(0.0, rg_v.x * sin(rg_ang0) - rg_v.y * cos(rg_ang0));
}
float rg_id = rg_i * 2.0 + rg_side;

float rg_wob = sin(u_time * u_rings_speed * (1.0 + rg_hash(rg_id + 3.0)) + rg_hash(rg_id + 7.0) * 6.28318);
float rg_rot = radians(u_rings_twist) * (rg_hash(rg_id) * 2.0 - 1.0) * (0.6 + 0.4 * rg_wob);
float rg_sh = u_rings_shift * (rg_hash(rg_id + 1.0) * 2.0 - 1.0) * (0.6 + 0.4 * rg_wob);
float rg_z = 1.0 + u_rings_zoom * (rg_hash(rg_id + 2.0) - 0.5) * 2.0;
if (rg_i < 0.5) {
    rg_rot *= 0.3;
    rg_sh *= 0.3;
}

float rg_cs = cos(rg_rot);
float rg_sn = sin(rg_rot);
vec2 rg_q = vec2(rg_v.x * rg_cs - rg_v.y * rg_sn, rg_v.x * rg_sn + rg_v.y * rg_cs) / rg_z;
vec2 rg_dir = rg_d > 0.001 ? rg_v / rg_d : vec2(0.0);
rg_q += rg_dir * rg_sh;
vec4 rg_col = texture2D(tex0, clamp((rg_c + rg_q) / rg_size, vec2(0.0), vec2(1.0)), u_lod_bias);

// 고리 경계선
float rg_edge = min(fract(rg_d / rg_w), 1.0 - fract(rg_d / rg_w)) * rg_w;
float rg_ln = (1.0 - smoothstep(0.5, 1.6, rg_edge)) * u_rings_line * step(0.5, rg_i + step(rg_w * 0.5, rg_d));
rg_col.rgb = mix(rg_col.rgb, u_rings_line_color * rg_col.a, clamp(rg_ln, 0.0, 1.0));

gl_FragColor = mix(rg_orig, rg_col, clamp(u_rings_strength, 0.0, 1.0));

glsl.fragment_functions:
float rg_hash(float n) {
    return fract(sin(n * 78.233 + 12.9898) * 43758.5453);
}

glsl.variables:
uniform sampler2D tex0;
uniform float u_lod_bias;
uniform float u_time;
uniform vec2 u_model_size;
attribute vec2 a_tex_coord;
varying vec2 v_tex_coord;

uniform float u_rings_strength;
uniform float u_rings_center_x;
uniform float u_rings_center_y;
uniform float u_rings_width;
uniform float u_rings_twist;
uniform float u_rings_shift;
uniform float u_rings_zoom;
uniform float u_rings_speed;
uniform float u_rings_halves;
uniform float u_rings_line;
uniform vec3 u_rings_line_color;
